INSERT INTO `TARMED_EXTENSION` VALUES ('17.0080-20070401-KVG',X'','Bei versicherungsmedizinischen, arbeitsmedizinischen und sportmedizinischen Fragestellungen.\r\n\r\nFahrrad oder Laufband.\r\n\r\nMin. 6 Ableitungen.\r\n\r\nLaufende {EKG}-Überwachung am Monitor.\r\n\r\nEngmaschige Blutdruckkontrolle (min. 1 x pro Belastungsstufe).\r\n\r\nMin. 2 Belastungsstufen, vorbehältlich medizinisch bedingten Abbruchs.\r\n\r\nInkl. Elektrokardiogramm ({EKG}) gemäss (17.0010).',NULL,'A16f995268e7b2d9c068477',1511528291256,'0');
