INSERT INTO `TARMED_EXTENSION` VALUES ('00.2285-20180101-KVG',X'','Nicht formalisierte Berichte sind in der Gestaltung frei und umfassen zwischen 11 und 35 Zeilen Text. Gilt auch für den Schriftverkehr unter Ärzten betreffend Befund, Diagnose, Therapien, Prognose über den Heilungsverlauf und weitere Massnahmen den Patient betreffend; dieser ist dem Versicherer auf Verlangen kostenlos zuzustellen, siehe hierzu auch KI-[00.06-8] und {14}.\r\n\r\nNicht abrechenbar sind kleine Zeugnisse, Mitteilungen an Patienten sowie alle weiteren kleinen Berichte (bis 10 Zeilen Text auf einer A4-Seite); diese sind Bestandteil von Allgemeinen Grundleistungen, siehe KI-[00.06-7] und (00.2255).',NULL,'A1db2070f4d21a472085277',1511528317504,'0');
