INSERT INTO `TARMED_EXTENSION` VALUES ('30.5211-20031201',X'',NULL,'Diese Position gilt als Fallkostenstabilitäts-Kompensation bei MRI-Leistungen an UV/MV/IV-Patienten.\r\n\r\nDiese Position ist gültig ab 1.12.2003. Sie gilt für die Dauer der Fallkostenstabilitäts-Periode und kann in der Höhe je nach Verlauf der Fallkosten der MRI-Leistungen geändert werden.\r\n\r\nNur verrechenbar im Zusammenhang mit einer oder mehreren MRI-Leistungen.\r\n\r\nNur anwendbar durch privatrechtlich geführte, eigenständige Radiologie-Institute mit ihren freipraktizierenden oder angestellten Radiologen.\r\n\r\nDie Rechnungsstellung muss unter Angabe der EAN des behandelnden Arztes erfolgen.\r\n\r\nDer Radiologe muss dem TARMED-Vertrag beigetreten sein, an der Dignitätserhebung der FMH teilgenommen haben und sich gegenüber den Versicherern über die qualitative Dignität Medizinische Radiologie / Radiodiagnostik ausweisen können.','A337cc8b554416ee6018777',1511528419339,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('30.06.07-20060401',NULL,NULL,NULL,'A33924b8b1f15d491098427',1511528388991,'0');
