INSERT INTO `TARMED_EXTENSION` VALUES ('28.0130-20010101-KVG',X'','Als Anästhesiezeit gilt die im Tarif festgelegte Zeit für die Leistung im engeren Sinne und die Zeit für Vor- und Nachbereitung.\r\n\r\nBei Tarifpositionen ohne festgelegte Zeit für die Leistung im engeren Sinne, gilt die Schnitt-Naht-Zeit bei operativen Eingriffen bzw. die Untersuchungszeit gemäss Anästhesieblatt bei diagnostischen Eingriffen; bei Mehrfacheingriffen gelten die in den Tarifpositionen aufgeführten Risikoklassen.\r\n\r\nAnästhesieleistung ohne erhöhtes Risiko: operative Versorgung an Extremitäten (ausgenommen grössere orthopädische operative Versorgungen, siehe Risikoklasse II und Risikoklasse III), Weichteiloperationen am Rumpf inkl. Inguinalhernien und Femoralhernien, Appendektomien, operative Versorgung am äusseren männlichen/weiblichen Genitale, Curettagen, Hysteroskopien, operative Versorgung an Portio.\r\n\r\nKinder bis 2 Jahren Risikoklasse III.\r\n\r\nBei einer Schnellschnittuntersuchung können für intraoperatives Warten 1 x pro Eingriff 35 Min. zusätzlich zur tarifarischen Leistung im engeren Sinne und Vor- und Nachbereitung abgerechnet werden.',NULL,'A3418dc6a4e55ab8e078177',1511528306601,'0');
