INSERT INTO `TARMED_EXTENSION` VALUES ('32.0655-20141001',X'','Therapie mit adaptiertem/dediziertem Bestrahlungsgerät.\r\n\r\nBeinhaltet Überprüfung der Indikation, Festlegung des Untersuchungsganges, Weisungen und Erklärungen an Fachpersonal und Patienten. {TL} und {AL} beinhalten abschliessend die Aktivitäten zur\r\n\r\n1. Vorbereitung: {CT}/{MRI}/Angio Grundleistungen, {OP}-Benützung, Zielpunktbestimmung mit Anlegen des Rahmens, allfällige Anästhesieleistungen in der Vorbereitung.\r\n\r\n2. Bestrahlungsphase: Die Planung, Zuschlag für aufwändige Planung und die Einmalbestrahlung.\r\n\r\nAm Bestrahlungstag sind somit keine weiteren Aufnahmen im Schädel-Hirnbereich mit {CT} oder {MRI} möglich. Nicht inbegriffen sind Leistungen der Tagesklinik.',NULL,'ad88355390dfe9043020060',1511528421358,'0');
