INSERT INTO `TARMED_EXTENSION` VALUES ('38.0300-20010101',X'','Inkl. Spirometrie gemäss (15.0130); inkl. Grundtaxe Röntgen Arztpraxis gemäss (39.0021); inkl. technische Grundleistung gemäss (39.2000); inkl. Thoraxradiografie gemäss (39.0190); inkl. kleiner Arztbericht gemäss (00.2255).\r\n\r\nZusätzlich sind gemäss Analysenliste mit Tarif (AL) verrechenbar:\r\n\r\n1224.00 Calcium Total in einer weiteren Körperflüssigkeit\r\n1223.00 Calcium Total im Blut \r\n1740.00 Urinteilstatus \r\n1666.00 Blutsenkung \r\n1370.00 Hämatogramm I \r\n1356.00 Glukose \r\n1509.00 Kreatinin \r\n1201.00 Beta-2-Mikroglobulin',NULL,'aec18e8e27a512dd3021110',1511528422968,'0');
