INSERT INTO `TARMED_EXTENSION` VALUES ('28.0130-20010101',X'','Als Anästhesiezeit gilt die im Tarif festgelegte Zeit für die Leistung im engeren Sinne und die Zeit für Vor- und Nachbereitung.\r\n\r\nBei Tarifpositionen ohne festgelegte Zeit für die Leistung im engeren Sinne, gilt die Schnitt-Naht-Zeit bei operativen Eingriffen bzw. die Untersuchungszeit gemäss Anästhesieblatt bei diagnostischen Eingriffen; bei Mehrfacheingriffen gelten die in den Tarifpositionen aufgeführten Risikoklassen.\r\n\r\nAnästhesieleistung ohne erhöhtes Risiko: operative Versorgung an Extremitäten (ausgenommen grössere orthopädische operative Versorgungen, siehe Risikoklasse II und Risikoklasse III), Weichteiloperationen am Rumpf inkl. Inguinalhernien und Femoralhernien, Appendektomien, operative Versorgung am äusseren männlichen/weiblichen Genitale, Curettagen, Hysteroskopien, operative Versorgung an Portio.\r\n\r\nKinder bis 2 Jahren Risikoklasse III.\r\n\r\nBei einer Schnellschnittuntersuchung können für intraoperatives Warten 1 x pro Eingriff 35 Min. zusätzlich zur tarifarischen Leistung im engeren Sinne und Vor- und Nachbereitung abgerechnet werden.',NULL,'b167c1f11d48a664c017173',1511528416926,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('32.0655-20141001-KVG',X'','Therapie mit adaptiertem/dediziertem Bestrahlungsgerät.\r\n\r\nBeinhaltet Überprüfung der Indikation, Festlegung des Untersuchungsganges, Weisungen und Erklärungen an Fachpersonal und Patienten. {TL} und {AL} beinhalten abschliessend die Aktivitäten zur\r\n\r\n1. Vorbereitung: {CT}/{MRI}/Angio Grundleistungen, {OP}-Benützung, Zielpunktbestimmung mit Anlegen des Rahmens, allfällige Anästhesieleistungen in der Vorbereitung.\r\n\r\n2. Bestrahlungsphase: Die Planung, Zuschlag für aufwändige Planung und die Einmalbestrahlung.\r\n\r\nAm Bestrahlungstag sind somit keine weiteren Aufnahmen im Schädel-Hirnbereich mit {CT} oder {MRI} möglich. Nicht inbegriffen sind Leistungen der Tagesklinik.',NULL,'b16afeee1e18c94d2081073',1511528311222,'0');
