INSERT INTO `TARMED_EXTENSION` VALUES ('04.1100-20010101-KVG',X'','Wundversorgung beinhaltet:\r\n\r\n- Débridement/Auffrischen Wundrand und Wundgrund\r\n- Entfernen von Schmutz/Fremdkörpern\r\n- Wundspülung\r\n- Wundrandmobilisierung\r\n- Glatter und spannungsfreier Wundverschluss (Direktverschluss)\r\n- allf. Drainage.\r\n\r\nBei traumatischer Gelenkeröffnung kann die entsprechende Arthrotomietarifposition verrechnet werden.',NULL,'b2190d0860e35ac44062073',1511528281035,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('28.0120-20010101-KVG',X'','Monitored Anesthesia Care (MAC):\r\n\r\nÜberwachung mit oder ohne Sedation und/oder Analgesie auf Verlangen des behandelnden Facharztes bei Eingriffen und diagnostischen Massnahmen mit und ohne vom behandelnden Facharzt gesetzten Lokalanästhesien.\r\n\r\nVoraussetzungen:\r\n\r\n- Perioperative Betreuung durch den Anästhesisten\r\n- Der Anästhesist befindet sich während des Eingriffes/der Massnahme am Patienten und überwacht diesen.\r\n- Der Patient bleibt auf Ansprache weckbar und seine Spontanatmung ohne mechanische Unterstützung suffizient.\r\n\r\nAls Anästhesiezeit gilt die im Tarif festgelegte Zeit für die Leistung im engeren Sinne und die Zeit für Vor- und Nachbereitung. \r\n\r\nBei Leistungen ohne hinterlegte Risikoklasse kann Monitored Anesthesia Care (MAC) abgerechnet werden, sofern die Voraussetzungen dafür gegeben sind. Als Anästhesiezeit gilt die im Tarif festgelegte Zeit für die Leistung im engeren Sinne und die Zeit für Vor- und Nachbereitung. Bei Tarifpositionen ohne festgelegte Zeit für die Leistung im engeren Sinne, gilt die Schnitt-Naht-Zeit bei operativen Eingriffen bzw. die Untersuchungszeit gemäss Anästhesieblatt bei diagnostischen Eingriffen; bei Mehrfacheingriffen gelten die in den Tarifpositionen aufgeführten Risikoklassen.\r\n\r\nBei einer Schnellschnittuntersuchung können für intraoperatives Warten 1 x pro Eingriff 35 Min. zusätzlich zur tarifarischen Leistung im engeren Sinne und Vor- und Nachbereitung abgerechnet werden.',NULL,'b2197f6097c5a1f93078173',1511528306593,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('30.0020-20070401-KVG',X'','Nur mit Tarifpositionen - Darstellung ohne Kontrastmittel - und Sparte Röntgenraum I kumulierbar.\r\n\r\nNicht abrechenbar durch Röntgeninstitute und Spitäler.',NULL,'B21ade21b5973dabc078388',1511528306963,'0');
