INSERT INTO `TARMED_EXTENSION` VALUES ('00.2540-20090301',X'','Notfallkriterien (tarifarisch):\r\n\r\n- Medizinisch notwendig und/oder vom Patienten, Angehörigen oder Dritten als offensichtlich notwendig erachtet\r\n- Der Facharzt befasst sich sofort, verzugslos mit dem Patienten bzw. sucht ihn auf. \r\n- Es wird ein direkter und unmittelbarer Arzt - Patienten - Kontakt vorausgesetzt. Ausnahme: Vergebliche Fahrt zum Unfallort/Ereignisort.\r\n- Besuche: zuhause, Altersheim, Unfallort, Ereignisort usw..\r\n\r\nFür die Entschädigung massgebend ist der Zeitpunkt des ersten, direkten und unmittelbaren Arzt - Patienten - Kontakts (Ausnahme: Bei Notfallbesuch gilt die Startzeit).\r\n\r\nDarf nur von nicht vom Spital oder Institut fix besoldeten Fachärzten abgerechnet werden.\r\n\r\nBei Einsätzen im Spital oder Institut gilt:\r\n\r\nDer Facharzt begibt sich für den ungeplanten, notfallmässigen Einsatz von ausserhalb ins Spital oder Institut. Hiermit abgegolten ist auch die Wegentschädigung. Fachärzte, welche vom Spital oder Institut ganz oder teilweise fix besoldet sind, haben kein Anrecht auf Verrechnung dieser Tarifposition.',NULL,'bc272b66ce1fde45e023',1511528390994,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('24.03.01-20010101-KVG',NULL,NULL,NULL,'Bc29aecc67962fb12058938',1511528276157,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('39.0090-20080101',X'','Zuschlag von 100% ({AL} und {TL}) für Kontrollaufnahmen nach therapeutischen Leistungen. Bedeutet Aufhebung einer Kumulationseinschränkung u/o ermöglicht nochmalige Verrechnung einer ersten Aufnahme.\r\n \r\nNur kumulierbar mit bildgebenden Leistungen, die nach einer Therapie eine Kontrollaufnahme zulassen.',NULL,'Bc2a285204544d185021288',1511528423225,'0');
