INSERT INTO `TARMED_EXTENSION` VALUES ('36.0110-20010101-KVG',X'','Gilt für ärztliche Leistungen direkt am und für den Patienten durch den vom Spital oder Institut fix besoldeten Spitalarzt. \r\n\r\nDie technische Leistung wird über die Tarifpositionen (36.0120) und (36.0130) Nichtärztliche Betreuung in der nicht anerkannten Notfallaufnahme entschädigt. \r\n\r\nWird der Patient im Anschluss an die ärztliche Leistung hospitalisiert, kann diese Tarifposition nicht abgerechnet werden; diese Tarifposition kann nur solange abgerechnet werden, als keine anderen Leistungen ausserhalb Kapitel [36] erbracht werden.',NULL,'Bcc27e0d4d3771fc2081688',1511528312111,'0');
