INSERT INTO `TARMED_EXTENSION` VALUES ('34.0310-20010101-KVG',X'','Die pflegerischen Leistungen kommen nur bei einem stationären Aufenthalt zur Anwendung. \r\n\r\nDie pflegerischen Leistungen Verbrennungs-{IPS} beinhalten die Benutzung der Räumlichkeiten sowie der Geräte und Instrumente, die pflegerischen Tätigkeiten (Grundpflege und Behandlungspflege) inkl. Analysen, welche vom {IPS}-Personal mit den dort zur Verfügung stehenden Laborgeräten und Materialien vorgenommen werden können. \r\n\r\nDie diversen Tätigkeiten, z.B. Zeit für die Vor- und Nachbereitung der Verbrennungseinheit, Einrichten und Sterilisieren von Beatmungsgeräten, Infusomaten, Injektionsgeräten, Überwachungsgeräten usw. sind in dieser Tarifposition einberechnet. \r\n\r\nBei jedem Eintritt in die Verbrennungs-{IPS} kann für die ersten 2 Std., unabhängig von der Patientenkategorie, diese Tarifposition abgerechnet werden. \r\n\r\nNach Ablauf der ersten 2 Std. wird der Patient in eine der 4 {SGI}-Pflegekategorien eingeteilt.',NULL,'Bfcd0bdf6719ec3df081488',1511528311815,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('20.0740-20010101',X'',NULL,NULL,'bfcf616eb21e00c7b09773',1511528405833,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('22.0110-20180101-KVG',X'','Betrifft nicht Blutstillung.',NULL,'Bfcfc12a82e2184b4092588',1511528328849,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('00.0095-20180101-KVG',X'','Entschädigt wird die reine Fahrzeit, unabhängig vom gewählten Fahrzeug, bzw. die Wegzeit als Fussgänger. \r\n\r\nDie für die Wegentschädigung massgebliche Zeit beginnt beim Verlassen des Praxisstandortes des Facharztes und endet mit dem Eintreffen beim Patienten. \r\n\r\nBeim Besuch mehrerer Patienten in der gleichen Besuchstour kann nur die für den Ortswechsel vom vorherigen zum nächsten Patienten aufgewendete Zeit abgerechnet werden. \r\n\r\nDie Wegentschädigung für die Rückkehr bemisst sich nach der Zeit für die Fahrt/Weg vom letzten Patienten zum Praxisstandort/Ausgangsort. \r\n\r\nBei Notfallbesuchen ist der effektive Standort des Facharztes massgeblich für die Berechnung der zum Besuch notwendigen Fahrzeit, solange sich dieser Standort innerhalb des Notfallkreises befindet. \r\n\r\nBefindet sich der Facharzt ausserhalb seines Notfallkreises, so ist die Fahrzeit ab Erreichen dessen Grenzen massgeblich. \r\n\r\nBei einem vergeblichen, notfallmässigen Besuch können die Weggebühr sowie ein Besuch à 5 Min. abgerechnet werden. \r\n\r\nTransportkosten sind in dieser Leistung inbegriffen. \r\n\r\nIm Zusammenhang mit Konsilien dürfen Wegentschädigungen nur verrechnet werden, wenn der Patient nicht transportfähig ist und das Konsilium in der Praxis des zu beratenden Facharztes durchgeführt werden muss bzw. wenn die Anwesenheit des zu beratenden Arztes beim Konsilium ausserhalb seiner Praxis medizinisch unabdingbar ist (z.B. am Krankenbett). \r\n\r\nGilt nicht für Konsilien im Spital.\r\n\r\nGilt nicht für die Wegzeit des Belegarztes zwischen der Arztpraxis und dem Belegspital.',NULL,'bfd40c3367326829a060023',1511528277429,'0');
