INSERT INTO `TARMED_EXTENSION` VALUES ('34.0310-20010101',X'','Die pflegerischen Leistungen kommen nur bei einem stationären Aufenthalt zur Anwendung. \r\n\r\nDie pflegerischen Leistungen Verbrennungs-{IPS} beinhalten die Benutzung der Räumlichkeiten sowie der Geräte und Instrumente, die pflegerischen Tätigkeiten (Grundpflege und Behandlungspflege) inkl. Analysen, welche vom {IPS}-Personal mit den dort zur Verfügung stehenden Laborgeräten und Materialien vorgenommen werden können. \r\n\r\nDie diversen Tätigkeiten, z.B. Zeit für die Vor- und Nachbereitung der Verbrennungseinheit, Einrichten und Sterilisieren von Beatmungsgeräten, Infusomaten, Injektionsgeräten, Überwachungsgeräten usw. sind in dieser Tarifposition einberechnet. \r\n\r\nBei jedem Eintritt in die Verbrennungs-{IPS} kann für die ersten 2 Std., unabhängig von der Patientenkategorie, diese Tarifposition abgerechnet werden. \r\n\r\nNach Ablauf der ersten 2 Std. wird der Patient in eine der 4 {SGI}-Pflegekategorien eingeteilt.',NULL,'c16259bb9732ef73f020471',1511528421967,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('04.0130-20010101',X'','Arztleistung: Injektion, Anwesenheit des Facharztes in Praxis, Ablesen, Interpretieren.\r\n\r\nGilt nicht für intrakutane Injektionen ausserhalb Dermatologie/Allergologie z.B. Mantoux.',NULL,'c1629a27de48e93710471',1511528391677,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('04.2930-20180101-KVG',X'','Regionen: Bauchdecke, obere Extremität pro Seite, Hüftpolster inkl. Gesässpolster pro Seite, Oberschenkelinnenseite pro Seite, Oberschenkelaussenseite pro Seite, Hals (ohne Nacken) inkl. Kinn, Knie pro Seite, eventuell andere Körperteile. \r\n\r\nGilt auch für operative Sekundärversorgung.\r\n\r\nRegionen siehe KI-[39-13].',NULL,'c16716bc321cad623086421',1511528319241,'0');
