INSERT INTO `TARMED_EXTENSION` VALUES ('35.0110-20010101',X'','Postoperative (inkl. apparativer) Überwachung stationärer Patienten bis zur Stabilisation der vitalen Funktionen: Allgemeinzustand, Bewusstsein, Blutdruck, Puls, Pupillenreaktion, Zentralvenendruck.\r\n\r\nMedikation: Injektionen, Infusionen und Bluttransfusionen usw. \r\n\r\nBehandlung: Absaugen oral/nasal, {O2}-Verabreichung, Drainage/Spülung, Verbandwechsel, Dokumentation, Patientenübergabe, Instruktionen usw.\r\n\r\nGilt nur bei stationärer Behandlung in separatem, zweckgebundenen, an den {OP}-Bereich angegliederten Aufwachraum.',NULL,'C2b835aae51a39f53020582',1511528422122,'0');
