INSERT INTO `TARMED_EXTENSION` VALUES ('50.0020-20040401',X'','Als anrechenbare Zeit gilt die im Tarif festgelegte Zeit für die Leistung im engeren Sinne, für Vor- und Nachbereitung und Bericht.\r\n\r\nGilt nur für Operationen/Interventionen im Spital im Spital an ambulanten oder stationären Patienten durch die nicht vom Spital fix besoldete belegärztliche Assistenz, die dem Vertrag zwischen der {MTK}/{MV}/{IV} und der {FMH}/{SBV} beigetreten ist.\r\n\r\nNur verrechenbar, sofern im Tarif eine Assistenz vorgesehen ist und die belegärztliche Assistenz während der Behandlung auch tatsächlich anwesend war.\r\n\r\nNur verrechenbar für die erste Assistenz.','Nur am Tag der Operation/Intervention abrechenbar.','ce8d7c2aad9d7f1c3023571',1511528426543,'0');
