INSERT INTO `TARMED_EXTENSION` VALUES ('32.0665-20080101',X'','Diese Zuschlagsleistung gilt alle Leistungen gemäss den Tarifpositionen (28.0050), (28.0100) und (28.0150) ab.\r\n\r\nMonitored Anesthesia Care (MAC) ist in der Hauptleistung ((32.0660)) inbegriffen.',NULL,'cfd55513e8e649fff020071',1511528421376,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('30.2890-20010101-KVG',X'','Beinhaltet Schilddrüse, Nebenschilddrüsen, Gefässe, Lymphknoten, Speicheldrüsen (inkl. Parotis), Muskelgruppen bis und mit Zunge, Mundboden.',NULL,'cfd9aba30def1b097079371',1511528308493,'0');
