INSERT INTO `TARMED_EXTENSION` VALUES ('09.0015-20180101-KVG',X'','Fachspezifische Anamnese, klinische Beurteilung Ohr, Ohrmuschel, Gehörgang und Trommelfell mit Ohrmikroskop/Lupe, Stimmgabelprüfung (Weber, Rinné), Flüsterzahlen, Beurteilung der vorderen Nasenräume mit Spekulum (vordere Rhinoskopie). \r\n \r\nBeurteilung von Epipharynx mit Spiegel; eventuell Beurteilung der Sinus maxillaris mittels Diaphanoskopie; visuelle Beurteilung von Lippe, Gebiss, Zahnfleisch, Zunge, Mundschleimhaut, Tonsillen, Mesopharynx (enoraler Status). \r\n \r\nBeurteilung von Hypopharynx und Larynx mittels Spiegel (indirekte Laryngoskopie); äussere Palpation von Hals und Nacken.',NULL,'Dd4053a52f9922dcc088681',1511528322676,'0');
