INSERT INTO `TARMED_EXTENSION` VALUES ('00.0167-20180101-KVG',X'','Gilt für diagnostische Leistungen an Instituten für Pathologie/Histologie/Zytologie in Abwesenheit des Patienten.\r\n\r\nAbrechenbar im Ausnahmefall bei Patienten über 6 Jahren und unter 75 Jahren mit einem erhöhten Behandlungsbedarf.\r\nDie Gründe für den erhöhten Behandlungsbedarf eines Patienten müssen in der Patientenakte aufgeführt werden. Der erhöhte Behandlungsbedarf eines Patienten ist gegenüber dem Versicherer zu begründen.\r\n\r\nKann bei diagnostischen Leistungen an Instituten für Pathologie/Histologie/Zytologie 5x pro Einsendung abgerechnet werden; dies gilt nicht für Zytologie zur Krebsvorsorge siehe (37.0700).\r\n\r\nMenge: gemäss Limitation in LG-11',NULL,'e1108b72435168963084752',1511528316742,'0');
