INSERT INTO `TARMED_EXTENSION` VALUES ('37.0220-20180101-KVG',X'','Inkl. Protokollierung der makroskopischen Befunde und Probenentnahme für Histologie.\r\n\r\nBeispiele: Beurteilen und Zuschneiden eines grösseren Hautexzisates mit Entnahme der Resektionsränder, Mammaexzisate, einfaches Hysterektomiepräparat, Kolonresektat bei Divertikulose.\r\n\r\nMax. 1 x pro Topografie/Lokalisation abrechenbar, unabhängig von der Anzahl Proben.',NULL,'E213a4a8b4f6e256a095880',1511528334071,'0');
