INSERT INTO `TARMED_EXTENSION` VALUES ('28.0060-20180101-KVG',X'','Bei Mehrfacheingriffen kommt die höher verrechenbare Risikoklasse zur Anwendung. \r\n\r\nDie perioperative Betreuung beinhaltet: Prämedikation am Vortag oder am Operationstag mit persönlicher Visite des Anästhesisten, allenfalls auch ambulant vorgezogen; postoperative ärztliche Behandlung am Operationstag in der Aufwachstation oder auf der Krankenabteilung bis zum Arbeitsbeginn des nächsten Tages u/o bei {IPS}-Patienten bis eine Stunde nach Operationsende.\r\n\r\nAnästhesieleistung mit sehr hohem Risiko: operative Versorgung am Herzen und thorakalen grossen Gefässen, kombinierte thorakoabdominale operative Versorgung und abdominelle Aorta, grössere operative Versorgung im Bereich des zentralen Nervensystems (cerebrale Tumoren, Hirnbasisaneurysmata).',NULL,'e25a9d1c999bf76a5095352',1511528333225,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('24.0850-20141001-KVG',X'',NULL,NULL,'e25ad62d54ab9b109074402',1511528300398,'0');
