INSERT INTO `TARMED_EXTENSION` VALUES ('34.0010-20040701-KVG',X'','Bei jedem Eintritt in die {IPS} kann für die ersten 2 Std., unabhängig von der Patientenkategorie, diese Tarifposition abgerechnet werden.\r\n\r\nNach Ablauf der ersten 2 Std. wird der Patient in eine der 4 {SGI}-Pflegekategorien eingeteilt.',NULL,'e25b3691c42e987fa081452',1511528311753,'0');
