INSERT INTO `TARMED_EXTENSION` VALUES ('13.0090-20010101-KVG',X'','z.B. Resektion von Neoplasien (Durchmesser mehr als 2 cm), Behandlung ausgedehnter Stenosen, Missbildungen.',NULL,'E27b5134ab5e1eb79067580',1511528289881,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('28.0150-20180101-KVG',X'','Als Anästhesiezeit gilt die im Tarif festgelegte Zeit für die Leistung im engeren Sinne und die Zeit für Vor- und Nachbereitung. \r\n\r\nBei Tarifpositionen ohne festgelegte Zeit für die Leistung im engeren Sinne, gilt die Schnitt-Naht-Zeit bei operativen Eingriffen bzw. die Untersuchungszeit gemäss Anästhesieblatt bei diagnostischen Eingriffen; bei Mehrfacheingriffen gelten die in den Tarifpositionen aufgeführten Risikoklassen. \r\n\r\nAnästhesieleistung mit stark erhöhtem Risiko:\r\n\r\n- Laparotomien (ausgenommen Appendektomie )\r\n- Thorakotomien\r\n- Lumbotomien\r\n- Kraniotomien\r\n- Wirbelsäulenoperationen\r\n- laparoskopische, thorakoskopische Eingriffe\r\n- maxilläre, rhinologische, orale, pharyngeale, laryngologische Eingriffe\r\n- Endoskopien über Mund/Nase\r\n- Kinder bis zu 2 Jahren (ausgenommen operative Versorgung Risikoklasse IV).\r\n\r\nBei einer Schnellschnittuntersuchung können für intraoperatives Warten 1 x pro Eingriff 35 Min. zusätzlich zur tarifarischen Leistung im engeren Sinne und Vor- und Nachbereitung abgerechnet werden.',NULL,'E27cd808a6eb9fa55095380',1511528333268,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('39.6390-20080101',X'',NULL,NULL,'E27e50062e14b9e66023180',1511528425917,'0');
