INSERT INTO `TARMED_EXTENSION` VALUES ('34.0460-20010101',X'','Die offene onkologische Pflegetechnik unterscheidet sich vom pflegerischen Aufwand nicht von der Normalpflege; der einzige Unterschied zur Normalpflege ist, dass diese Pflege in der Life-Island-Einheit erfolgt. \r\n\r\nDie offene onkologische Pflege dauert wenige Tage und dient v.a. letzten medizinischen Untersuchungen vor der Entlassung des Patienten.',NULL,'Ece2b2fddc9f6af69020530',1511528422047,'0');
