INSERT INTO `TARMED_EXTENSION` VALUES ('37.0070-20141001',X'','Nur verrechenbar bei auswärtig durchgeführten Autopsien.\r\n\r\nEntschädigt wird die reine Fahrzeit, unabhängig vom gewählten Fahrzeug, bzw. die Wegzeit als Fussgänger.\r\n\r\nDie für die Wegentschädigung massgebliche Zeit beginnt beim Verlassen des üblichen Arbeitsortes des Pathologen und endet mit dem Eintreffen am Standort der vorzunehmenden Autopsie.\r\n\r\nErfolgen anschliessend weitere Autopsien an anderen Standorten, kann nur die für den Ortswechsel aufgewendete Zeit abgerechnet werden.\r\n\r\nDie Wegentschädigung für die Rückkehr bemisst sich nach der Zeit für die Fahrt/Weg vom letzten Standort zum üblichen Arbeitsort des Pathologen.\r\n\r\nTransportkosten sind in dieser Leistung inbegriffen.',NULL,'Ee16a2044ddf1dace020730',1511528422340,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('00.0525-20180101-KVG',X'','Krisenintervention:\r\n\r\n- Behandlung bei Suchtverhalten und Suchterkrankung (psychotrope Substanzen, Alkohol, Nikotin)\r\n- Betreuung bei funktionellen/psychosomatischen Leiden, kindlichen/adoleszenten psychischen Entwicklungsstörungen, chronischen psychischen Erkrankungen usw.\r\n\r\nAm Symptom orientierte Behandlung, auf der Grundlage einer reflektierten, professionell gestalteten Arzt-Patient-Beziehung. \r\n\r\nBehandelt werden Patienten mit Erkrankungen im angestammten somatischen Fachgebiet, deren Gesundheitsstörungen wesentlich durch psychische Faktoren verursacht und/oder verstärkt werden.',NULL,'Ee18a8887e269f190084830',1511528316839,'0');
