INSERT INTO `TARMED_EXTENSION` VALUES ('37.0230-20010101',X'','Inkl. Protokollierung der makroskopischen Befunde und Probenentnahme für Histologie. \r\n\r\nBeispiele: Präparieren, Beurteilen und Zuschneiden von grossen Resektaten, meist wegen einer Neoplasie wie Pneumonektomie, Mammaamputat mit Axilla, radikales Prostatektomiepräparat mit Lymphknoten, Kolonresektate mit Lymphknoten.\r\n\r\nMax. 1 x pro Topografie/Lokalisation abrechenbar, unabhängig von der Anzahl Proben.',NULL,'ee7ae5c469d6922ec020802',1511528422446,'0');
