INSERT INTO `TARMED_EXTENSION` VALUES ('04.0920-20180101-KVG',X'','Fremdkörpertiefe: Massgebend ist der am tiefsten liegende Fremdkörper (Fremdkörperteil), gemessen im rechten Winkel zur Körperoberfläche.\r\n\r\nUnabhängig von der Anzahl Fremdkörper.\r\n\r\nInkl. Fremdkörpersuche, allf. bildgebende Techniken während Operation, allf. Direktverschluss.\r\n\r\nGilt nicht für reine Extraktion.',NULL,'Fe1e806e4c0099719086034',1511528318612,'0');
