INSERT INTO `TARMED_EXTENSION` VALUES ('34.0410-20070401-KVG',X'','Gilt nur für Patienten mit allogener Knochenmarktransplantation ({KMT}); siehe {KLV}. \r\n\r\nBeispiele: akute Leukämien nach Induktionstherapie, chronisch-myeloische Leukämien, schwere aplastische Anämien, myelodysplastische Syndrome, maligne Lyphome und Thalassaemia major; bei der onkologischen Sterilpflegetechnik werden die Patienten unter strikter Sterilpflege behandelt; dies heisst, die Pflege erfolgt unter sterilen Lüftungsbedingungen, die Patienten erhalten sterile Nahrung, es besteht eine spezielle Vorrichtung für die Magen-Darm-Dekontamination und der Patient erhält sterile Gebrauchsgegenstände. \r\n\r\nZur Pflege/Untersuchung des Patienten muss sich das Personal steril umziehen; die im Zusammenhang mit der onkologischen Sterilpflege erforderlichen speziellen Massnahmen, Leistungen, Gebrauchsmaterialien und Verbrauchsmaterialien (bis zum Einkaufspreis (inkl. MWST) pro Einzelstück von CHF 3.--) sind mit der Tarifposition abgegolten und können demzufolge nicht separat abgerechnet werden; mit dieser Leistung sind auch die während eines Wechsels durchzuführenden Tätigkeiten (Zimmer und Möbel sterilisieren, Zimmer steril einrichten, Bett, Desinfektionsplatz usw.) abgegolten.',NULL,'Fea209d4a93a753d1081534',1511528311875,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('20.0040-20010101',X'','Beinhaltet Débridement, Spülen, Einlegen Drain. \r\n\r\nGilt nicht für einfache Wundspreizung, die Bestandteil von Allgemeine Grundleistungen ist.',NULL,'fea48653e94c160f309463',1511528405468,'0');
