INSERT INTO `TARMED_EXTENSION` VALUES ('28.0100-20010101-KVG',X'','Bei Mehrfacheingriffen kommt die höher verrechenbare Risikoklasse zur Anwendung. \r\n\r\nAnästhesieleistung mit stark erhöhtem Risiko:\r\n\r\n- Laparotomien (ausgenommen Appendektomie )\r\n- Thorakotomien\r\n- Lumbotomien\r\n- Kraniotomien\r\n- Wirbelsäulenoperationen\r\n- laparoskopische, thorakoskopische Eingriffe\r\n- maxilläre, rhinologische, orale, pharyngeale, laryngologische Eingriffe\r\n- Endoskopien über Mund/Nase\r\n- Kinder bis zu 2 Jahren (ausgenommen operative Versorgung Risikoklasse IV).',NULL,'feda2fd2ee85dfb59078163',1511528306578,'0');
