INSERT INTO `TARMED_EXTENSION` VALUES ('23.0120-20180101-KVG',X'','Indirekt: Inzision nicht über tumorverdächtiger Läsion, z.B. periareolär, in Submammaerfalte.',NULL,'g403033d7375e23d7093214',1511528329757,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('28.0160-20070401',X'','Als Anästhesiezeit gilt die im Tarif festgelegte Zeit für die Leistung im engeren Sinne und die Zeit für Vor- und Nachbereitung.\r\n\r\nBei Tarifpositionen ohne festgelegte Zeit für die Leistung im engeren Sinne, gilt die Schnitt-Naht-Zeit bei operativen Eingriffen bzw. die Untersuchungszeit gemäss Anästhesieblatt bei diagnostischen Eingriffen; bei Mehrfacheingriffen gelten die in den Tarifpositionen aufgeführten Risikoklassen.\r\n\r\nAnästhesieleistung mit sehr hohem Risiko: operative Versorgung am Herzen und thorakalen grossen Gefässen, kombinierte thorakoabdominale operative Versorgung und abdominelle Aorta, grössere operative Versorgungen im Bereich des zentralen Nervensystems (cerebrale Tumoren, Hirnbasisaneurysmata).\r\n\r\nBei einer Schnellschnittuntersuchung können für intraoperatives Warten 1 x pro Eingriff 35 Min. zusätzlich zur tarifarischen Leistung im engeren Sinne und Vor- und Nachbereitung abgerechnet werden.',NULL,'G40442947efa01e00017187',1511528416953,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('04.1120-20141001-KVG',X'','Débridement beinhaltet: \r\n\r\n- Débridement/Auffrischen Wundrand und Wundgrund\r\n- Entfernen von Schmutz/Fremdkörpern\r\n- Wundspülung\r\n- allf. Situationsnähte\r\n- allf. Drainage.\r\n\r\nGilt nicht für Dekubitus, Ulkus, Verbrennungen\r\n\r\nBei traumatischer Gelenkeröffnung kann die entsprechende Arthrotomietarifposition verrechnet werden.',NULL,'G404858343fe0a47d062087',1511528281061,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('03.0310-20180101-KVG',X'','Inkl. allf. Untersuchung visueller, taktilkinästhetischer Wahrnehmung.',NULL,'G40518a4f0984ebc0085737',1511528318146,'0');
