INSERT INTO `TARMED_EXTENSION` VALUES ('35.0110-20070401',X'','Postoperative (inkl. apparativer) Überwachung stationärer Patienten bis zur Stabilisation der vitalen Funktionen: Allgemeinzustand, Bewusstsein, Blutdruck, Puls, Pupillenreaktion, Zentralvenendruck.\r\n\r\nMedikation: Injektionen, Infusionen und Bluttransfusionen usw. \r\n\r\nBehandlung: Absaugen oral/nasal, {O2}-Verabreichung, Drainage/Spülung, Verbandwechsel, Dokumentation, Patientenübergabe, Instruktionen usw.\r\n\r\nGilt nur bei stationärer Behandlung in separatem, zweckgebundenen, an den {OP}-Bereich angegliederten Aufwachraum.',NULL,'Ga3067c1693c3b52020587',1511528422129,'0');
