INSERT INTO `TARMED_EXTENSION` VALUES ('39.3710-20141001-KVG',X'','Einschliesslich Lokalanästhesie und Einbringen von Medikamenten\r\n\r\nUnabhängig von der Anzahl Läsionen\r\n\r\nUnabhängig von der Methode und Einlagen von Drainagekathetern',NULL,'gf7ea779bcddcf002083664',1511528315045,'0');
