INSERT INTO `TARMED_EXTENSION` VALUES ('28.0110-20010101',X'','Bei Mehrfacheingriffen kommt die höher verrechenbare Risikoklasse zur Anwendung. \r\n\r\nAnästhesieleistung mit sehr hohem Risiko: operative Versorgung am Herzen und thorakalen grossen Gefässen, kombinierte thorakoabdominale operative Versorgung und abdominelle Aorta, grössere operative Versorgungen im Bereich des zentralen Nervensystems (cerebrale Tumoren, Hirnbasisaneurysmata).',NULL,'h166469a448679212017165',1511528416912,'0');
