INSERT INTO `TARMED_EXTENSION` VALUES ('04.2540-20010101-KVG',X'','Beinhaltet Präparation und Débridement sowie Vereinigung des proximalen und distalen Stumpfes; inkl. allf. Muskelnähte.\r\n\r\nGilt auch bei noch bestehender, alleiniger Weichteilbrücke.\r\n\r\nGefässnähte (04.2620) und Nervennähte (04.0800) und (04.0810).\r\n\r\nGefässtransplantate ((04.1690) ff) und Nerventransplantate ((04.1730) ff).\r\n\r\nOsteosynthesen [07] und [10].\r\n\r\nSehnennähte (04.0720).',NULL,'h18df07dfa39a72d2062615',1511528282010,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('04.1080-20010101',X'','Wundversorgung beinhaltet: \r\n\r\n- Débridement/Auffrischen Wundrand und Wundgrund\r\n- Entfernen von Schmutz/Fremdkörpern\r\n- Wundspülung\r\n- Wundrandmobilisierung\r\n- Glatter und spannungsfreier Wundverschluss (Direktverschluss)\r\n- allf. Drainage.\r\n\r\nBei traumatischer Gelenkeröffnung kann die entsprechende Arthrotomietarifposition verrechnet werden.',NULL,'h18f5596a5205aa9701065',1511528392553,'0');
