INSERT INTO `TARMED_EXTENSION` VALUES ('00.2550-20180101-KVG',X'','Notfallkriterien Abend/Nacht/Wochenende (tarifarisch):\r\n \r\n- Bei direktem Arzt - Patientenkontakt: Vom Facharzt als medizinisch notwendig erachtet\r\n\r\n- Ohne direkten Arzt-Patientenkontakt: Medizinisch notwendig und/oder vom Patienten, Angehörigen oder Dritten als offensichtlich notwendig erachtet\r\n \r\n- Der Facharzt befasst sich sofort, verzugslos mit dem Patienten bzw. sucht ihn auf. \r\n \r\n- Es wird ein unmittelbarer Arzt - Patienten - Kontakt vorausgesetzt. Ausnahme: Vergebliche Fahrt zum Unfallort/Ereignisort.\r\n \r\n- Besuche: zuhause, Alters- und Pflegeheim, Unfallort, Ereignisort usw..\r\n \r\nFür die Entschädigung massgebend ist der Zeitpunkt des ersten, direkten und unmittelbaren Arzt - Patienten - Kontakts (Ausnahme: Bei Notfallbesuch gilt die Startzeit).\r\n \r\nZuschlag von 50% auf den Tarifpositionen, die in diesem Zeitraum für die Behandlung des entsprechenden Notfalls verrechnet werden.\r\n \r\nZuschlag nur auf die AL und nicht auf die TL der entsprechenden Tarifpositionen.\r\n \r\nDarf nur von nicht vom Spital oder Institut fix besoldeten Fachärzten abgerechnet werden.\r\n \r\nGilt nicht für Einsätze, welche im Spital oder Institut erbracht werden.',NULL,'h3be7c521752ce49a085415',1511528317671,'0');
