INSERT INTO `TARMED_EXTENSION` VALUES ('04.1100-20180101-KVG',X'','Wundversorgung beinhaltet:\r\n\r\n- Débridement/Auffrischen Wundrand und Wundgrund\r\n- Entfernen von Schmutz/Fremdkörpern\r\n- Wundspülung\r\n- Wundrandmobilisierung\r\n- Glatter und spannungsfreier Wundverschluss (Direktverschluss)\r\n- allf. Drainage.\r\n\r\nBei traumatischer Gelenkeröffnung kann die entsprechende Arthrotomietarifposition verrechnet werden.',NULL,'Hd39a89679b3a433f086090',1511528318689,'0');
