INSERT INTO `TARMED_EXTENSION` VALUES ('38.0010-20010101',X'','Inkl. Spirometrie gemäss (15.0130); inkl. Ruhe-{EKG} gemäss (17.0010); inkl. Belastungs-{EKG}, Ergometrie gemäss (17.0090); inkl. kleiner Arztbericht gemäss (00.2255). \r\n\r\nZusätzlich sind gemäss Analysenliste mit Tarif (AL) verrechenbar: \r\n\r\n1740.00 Urin-Teilstatus\r\n1396.00 Hämoglobin\r\n1509.00 Kreatinin, Blut/Plasma/Serum\r\n1532.00 Leukozytenzählung\r\n1356.00 Glukose, Blut/Plasma/Serum\r\n1341.00 Gamma-Glutamyltranspeptidase (GGT)\r\n1020.00 Alanin-Aminotransferase (ALAT)',NULL,'Hd53c1a10056cbe74020990',1511528422753,'0');
