INSERT INTO `TARMED_EXTENSION` VALUES ('39.2170-20141001',X'','Gilt für Leistungen ausserhalb der Röntgenabteilung mittels fahrbaren Röntgengeräten durch das Röntgenfachpersonal (z.B. Pflegeabteilung, {IPS} und anderes). Der Patient kann sich nicht selbständig oder mit Hilfe von Dritten zur Röntgenabteilung begeben.\r\n\r\nGilt nicht für Leistungen der Sparten: \r\n\r\n- Elektrophysiologisches Labor / Katheterplatz \r\n- Extrakorporale Stosswellen-Lithotripsie ({ESWL}) \r\n- Gastroenterologische Endoskopie, gross \r\n- Gastroenterologische Endoskopie, Spital \r\n- Gipsraum \r\n- {OP} I, {OP} II, {OP} III \r\n- Pneumologischer Endoskopieraum \r\n- {UBR} mit BV-TV \r\n- Urologische Funktionsdiagnostik \r\n- Urologischer Endoskopieraum',NULL,'hd5ca59e7c7591041022065',1511528424328,'0');
