INSERT INTO `TARMED_EXTENSION` VALUES ('00.0210-20010101-KVG',X'','Beinhaltet Aufklärung des Patienten unmittelbar vor der Operation/Intervention, Gespräche mit den für den Patienten zuständigen Personen, Visiten beim Patienten (inkl. Wundpflege, Verbandwechsel, Entfernung von Wundverschlussmaterial).\r\n\r\nDefinition Operation/Intervention siehe {4}.\r\n\r\nAbrechenbar am Eintrittstag, am Operationstag u/o Interventionstag, am ersten Tag nach der Operation u/o Intervention, sowie am ersten Tag nach der Geburt; nur einmal am selben Tag abrechenbar, falls Eintrittstag mit Operationstag u/o Interventionstag zusammenfällt.\r\n\r\nNur durch den hauptverantwortlich behandelnden Facharzt abrechenbar; für elektronisch abrechnende Fachärzte siehe (00.0310).',NULL,'hd7dab97ddd93bdd5060165',1511528277716,'0');
