INSERT INTO `TARMED_EXTENSION` VALUES ('28.0040-20070401',X'','Bei Mehrfacheingriffen kommt die höher verrechenbare Risikoklasse zur Anwendung.\r\n\r\nDie perioperative Betreuung beinhaltet: Prämedikation am Vortag oder am Operationstag mit persönlicher Visite des Anästhesisten, allenfalls auch ambulant vorgezogen; postoperative ärztliche Behandlung am Operationstag in der Aufwachstation oder auf der Krankenabteilung bis zum Arbeitsbeginn des nächsten Tages u/o bei {IPS}-Patienten bis eine Stunde nach Operationsende.\r\n\r\nAnästhesieleistung mit erhöhtem Risiko: Operation in Bauchlage; ophthalmologische, otologische, urologische Operationen (ohne Operationen am äusseren Genitale sowie an Nebennieren, Nieren, Nierenbecken und Ureteren); vaginale und geburtshilfliche operative Versorgung (Ausnahmen siehe Risikoklasse I und Risikoklasse III), operative Versorgung an Gesicht, Hals, Schultergürtel; grössere orthopädische Operationen (Hüftgelenk, Kniegelenkendoprothesen).\r\n\r\nKinder bis 2 Jahren Risikoklasse III.',NULL,'he0cbd1a66862ca23017115',1511528416849,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('24.4110-20070401-KVG',X'','Becken, Femurkopf, bis und mit Trochanteren.',NULL,'He0de2849f536ad30075640',1511528302623,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('04.2540-20010101',X'','Beinhaltet Präparation und Débridement sowie Vereinigung des proximalen und distalen Stumpfes; inkl. allf. Muskelnähte.\r\n\r\nGilt auch bei noch bestehender, alleiniger Weichteilbrücke.\r\n\r\nGefässnähte (04.2620) und Nervennähte (04.0800) und (04.0810).\r\n\r\nGefässtransplantate ((04.1690) ff) und Nerventransplantate ((04.1730) ff).\r\n\r\nOsteosynthesen [07] und [10].\r\n\r\nSehnennähte (04.0720).',NULL,'he121c75b45e4ad6f01615',1511528393399,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('39.3830-20080101',X'',NULL,NULL,'He142adc1c916c775022690',1511528425155,'0');
