INSERT INTO `TARMED_EXTENSION` VALUES ('00.0536-20180101-KVG',X'','Abrechenbar im Ausnahmefall bei Patienten über 6 Jahren und unter 75 Jahren mit einem erhöhten Behandlungsbedarf.\r\n\r\nDie Gründe für den erhöhten Behandlungsbedarf eines Patienten müssen in der Patientenakte aufgeführt werden. Der erhöhte Behandlungsbedarf eines Patienten ist gegenüber dem Versicherer zu begründen.\r\n\r\nErklärung der Bedeutung der klinischen und familienanamnestischen Befunde im Hinblick auf das Wiederholungsrisiko einer Erbkrankheit; Erläuterung der Zielsetzung und der Resultate einer spezialärztlichen genetischen u/o pränatalen Untersuchung.',NULL,'Hf132b0ee6852989084840',1511528316853,'0');
