INSERT INTO `TARMED_EXTENSION` VALUES ('00.2315-20050101-KVG',X'','Die Höhe des Expresszuschlags wird im Hinblick auf einen festgelegten Ablieferungstermin zwischen Auftraggeber und Auftragnehmer vereinbart. \r\n\r\nEr kann vom Auftragnehmer in Rechnung gestellt werden, falls die Terminvorgabe eingehalten wird. \r\n\r\nDie Tarifposition setzt sich nur aus einer ärztlichen Leistung ({AL}) zusammen. \r\n\r\nDie Anwendung bleibt besonderen Fällen vorbehalten; die Ausrichtung eines Expresszuschlags kann, wenn eine solche bei der Auftragerteilung nicht ausdrücklich vereinbart worden ist, nicht nachträglich eingefordert werden.\r\n\r\nAbrechnung gemäss spezieller Vereinbarung mit dem Kostenträger.',NULL,'Hf14de81a37526bc9060840',1511528278965,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('19.0610-20180101-KVG',X'',NULL,NULL,'Hf151699ccdedec60090840',1511528326159,'0');
