INSERT INTO `TARMED_EXTENSION` VALUES ('32.0660-20120601',X'','Therapie mit Gamma-Knife.\r\n \r\nBeinhaltet Überprüfung der Indikation, Festlegung des Untersuchungsganges, Weisungen und Erklärungen an Fachpersonal und Patienten. TL und AL beinhalten abschliessend die Aktivitäten zur \r\n\r\n1. Vorbereitung: OP-Benützung, Zielpunktbestimmung mit Anlegen des Rahmens, allfällige Anästhesieleistungen in der Vorbereitung. \r\n\r\n2. Bestrahlungsphase: Die Planung, Zuschlag für aufwändige Planung und die Einmalbestrahlung. \r\nEbenfalls inbegriffen ist eine allfällig durchgeführte Monitored Anesthesia Care (MAC).\r\n\r\nAngiografie, CT- und MRI- Aufnahmen im Schädel-Hirnbereich am Bestrahlungstag siehe Zuschlagsleistungen Pos. (32.0675), Pos. (32.0685) und Pos. (32.0695). \r\n\r\nNicht inbegriffen sind Leistungen der Tagesklinik. ',NULL,'hf37c07394242a840020065',1511528421367,'0');
