INSERT INTO `TARMED_EXTENSION` VALUES ('00.2420-20180101-KVG',X'','Für ausserordentlich schwierige Fälle sind Spezialabmachungen mit dem Auftraggeber zu treffen. Unter diese Kategorie gehören: ausserordentlich aufwändiges Aktenstudium, hohe Schwierigkeit der gutachterlichen Überlegungen und Schlussfolgerungen, ausserordentlich schwieriges Verfassen des Gutachtens mit ungewöhnlich umfangreichen Recherchen.\r\n\r\nAbrechnung gemäss spezieller Vereinbarung mit dem Kostenträger.',NULL,'i2b075d98bac914a2085358',1511528317608,'0');
