INSERT INTO `TARMED_EXTENSION` VALUES ('24.0230-20180101-KVG',X'','Definition Exploration: Eingehende chirurgische Darstellung zur sicheren Beurteilung der im verletzten Gebiet betroffenen Strukturen (Sehnen, Gefässe, Nerven).\r\n\r\nDefinition komplex: Verletzung unübersichtlich, Verdacht auf Verletzung von Sehnen, Sehnenanhangsgebilden, Gefässen, Nerven; inkl. Débridement; inkl. Blutstillung. \r\n\r\nNicht verrechenbar, wenn das Verletzungsmuster aufgrund der klinischen u/o apparativen Untersuchung bereits vor dem Eingriff feststeht, z.B. bei Amputationen.\r\n\r\nDie Exploration und Therapieplanung ist zwingend im OP-Bericht zu dokumentieren.\r\n',NULL,'If4f10a8e1c34774a093445',1511528330065,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('37.0330-20010101-KVG',X'','Inkl. mikroskopischer Beschreibung, Beurteilung mit Diagnose und Kommentar zur Befundung und zur klinischen Fragestellung, inkl. Auswertung von Spezialfärbungen, Spezialuntersuchungen. \r\n\r\nBeispiele: Zellveränderungen mit komplexer Differentialdiagnose, Vergleich mit Vorbefunden unumgänglich; Auswertung von Spezialfärbungen, Spezialuntersuchungen; Nachweis eines speziellen Erregers.',NULL,'If535c486c8746b34081845',1511528312343,'0');
