INSERT INTO `TARMED_EXTENSION` VALUES ('39.6290-20141001-KVG',X'','Das Grundelement Embolisation/intraarterielle Chemotherapie neuroradiologisch ist zusätzlich zu angiografischen Grundleistungen abrechenbar.\r\n\r\nInkl. Embolisation/intraarterielle Chemotherapien im Bereich von Ästen 1. Ordnung.\r\n\r\nInkl. Embolisationen/intraarterielle Chemotherapien im Bereich von Ästen 2. Ordnung und höherer Ordnung, erstes Segment/Feeder.\r\n\r\nInkl. Embolisationen/intraarterielle Chemotherapien in Cross-over Technik.\r\n\r\nInkl. Chemoembolisationen.',NULL,'J1516aca4a347eee8084143',1511528315804,'0');
