INSERT INTO `TARMED_EXTENSION` VALUES ('36.0020-20010101',X'','Die Tarifposition kann nur von einer Klinik mit Notfallversorgungsauftrag mit einer anerkannten Notfallaufnahme abgerechnet werden. \r\n\r\nDie pflegerischen Leistungen kommen nur bei Notfallpatienten zur Anwendung. Ein Notfallpatient wird definiert als Patient in der Notfallaufnahme einer Klinik, bei dem ein verzugsloses Handeln durch ärztliches und nichtärztliches Personal aus medizinischen Gründen erforderlich ist. Die pflegerischen Leistungen umfassen Patiententriage (z.B. Abklärung bezüglich Dringlichkeit und Behandlungsbedürftigkeit). \r\n\r\nInformationen weiterleiten oder einholen (Patient, Angehörige, andere Ansprechpartner).\r\n\r\nBeschaffung von Patientendaten (Krankengeschichte, Versicherung, externe Berichte usw.).\r\n\r\nOrganisation von Arbeitsabläufen, Weiterbehandlungen, diverse Untersuchungen, andere Betriebsstellen/Institutionen usw.; Patientenvorbereitung für weitere Behandlungen (z.B. ausziehen, waschen, prämedizieren usw.). \r\n\r\nMit dieser Leistung sind auch die während eines Wechsels durchzuführenden Tätigkeiten (Vorbereitung der Apparaturen, Messgeräte usw.; Bereitstellen von Liegen; Aufräumarbeiten und Reinigungsarbeiten; Medikamentenbestellungen und Materialbestellungen usw.) enthalten.\r\n\r\nAlle ärztlichen Leistungen sind nicht in dieser Tarifposition enthalten. Ärztliche Leistung in der Notfallstation siehe Tarifposition (36.0010).\r\n\r\nWird der Patient im Anschluss an die ärztliche Leistung hospitalisiert, kann diese Tarifposition nicht abgerechnet werden; diese Tarifposition kann nur solange abgerechnet werden, als keine anderen Leistungen ausserhalb Kapitel [36] erbracht werden.',NULL,'j1865dc46750f3323020666',1511528422254,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('39.7320-20141001-KVG',X'','Verrechenbar bei allen Leistungen des Kapitels [39.06], also auch bei Phlebografien.',NULL,'j187f1c22e98045af084516',1511528316428,'0');
