INSERT INTO `TARMED_EXTENSION` VALUES ('00.2505-20180101-KVG',X'','Dringlichkeitskriterien (tarifarisch): \r\n\r\n- Medizinisch notwendig und/oder vom Patienten, Angehörigen oder Dritten als offensichtlich notwendig erachtet. \r\n- Der Facharzt befasst sich spätestens innerhalb von 2 Stunden mit dem Patienten bzw. sucht ihn auf. \r\n- Es wird ein direkter und unmittelbarer Arzt - Patienten - Kontakt vorausgesetzt. Ausnahme: Vergebliche Fahrt zum Ereignisort. \r\n- Besuche: zuhause, Altersheim, Ereignisort usw.\r\n- Gilt nicht für Leistungen, die im Spital erbracht werden. \r\n\r\nFür die Entschädigung massgebend ist der Zeitpunkt des ersten, direkten und unmittelbaren Arzt - Patienten - Kontakts (Ausnahme: Bei einem dringlichen Besuch gilt die Startzeit). Darf nicht während einer regulären Sprechstunde (Abendsprechstunde, reguläre Sonntags-Sprechstunde) verrechnet werden. \r\n\r\nDie Behandlung von nicht angemeldeten Patienten gilt nicht generell als dringlich und berechtigt nicht generell zur Verrechnung der Dringlichkeits-Inkovenienzpauschale F.',NULL,'j39c9122d1afc609f085366',1511528317622,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('34.0440-20070401-KVG',X'','Gilt nur für Patienten mit langdauernder Knochenmarkaplasie. \r\n\r\nEs sind dies u.a.: akute Leukämien zur Chemotherapie, schwere aplastische Anämien, Strahlenunfälle und Chemotherapieüberdosierungen. \r\n\r\nZudem gilt die Ureterkatheter-Pflegetechnik als Zwischenstation von der Sterilpflegetechnik zur offenen Pflegetechnik; bei der onkologischen Ureterkatheter-Pflegetechnik werden die Patienten unter strikter Sterilpflege behandelt; dies heisst, die Pflege erfolgt unter sterilen Lüftungsbedingungen; die im Zusammenhang mit der onkologischen Ureterkatheter-Pflege erforderlichen speziellen Massnahmen, Leistungen, Gebrauchsmaterialien und Verbrauchsmaterialien (bis zum Einkaufspreis (inkl. MWST) pro Einzelstück von CHF 3.--) sind mit der Tarifposition abgegolten und können demzufolge nicht separat abgerechnet werden. \r\n\r\nMit dieser Leistung sind auch die während eines Wechsels durchzuführenden Tätigkeiten (Aufbereitung und Vorbereitung der Life-Island-Einheit (Zimmer Ausräumen, Material aufbereiten und sterilisieren, Grundreinigung und Desinfektion, Zimmer einrichten für allgemeine Ureterkatheter-Isolation) abgegolten.',NULL,'J39e12b856908bfca081543',1511528311890,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('24.1740-20180101-KVG',X'','Jede Methode: subtotale/totale.',NULL,'j39e36244c50b969a093716',1511528330513,'0');
