INSERT INTO `TARMED_EXTENSION` VALUES ('35.0510-20141001-KVG',X'','Die Position beinhaltet die nichtärztliche Betreuung von Patienten ausserhalb der Tagesklinik. \r\n\r\nNur verrechenbar bei medizinisch bedingtem Aufenthalt. \r\n\r\nGilt nicht für organisatorisch verursachte Wartezeiten.\r\n\r\nDie Tarifposition beinhaltet folgende Tätigkeiten durch nichtärztliches Personal: \r\n\r\n- Aufnahme des Patienten auf der Abteilung\r\n- Information und Anweisungen an den Patienten\r\n- Medikation und Wundpflege\r\n- Überwachung und Pflege bis zum Austritt\r\n\r\nInkl. Bettbenützung, Mahlzeiten und Getränke usw..\r\n\r\nGilt auch für die Betreuung/Überwachung vor und nach Behandlung in der allgemeinen Schmerztherapie sowohl im Spital als auch in der Arztpraxis.',NULL,'jf828f63cbf96cf8e081666',1511528312078,'0');
