INSERT INTO `TARMED_EXTENSION` VALUES ('39.3840-20080101',X'','Gilt für Leistungen ausserhalb der Ultraschallabteilung (z.B. Pflegeabteilung, {IPS} und anderes) mittels fahrbarem Ultraschallgerät unter Beizug von Fachpersonal. Der Patient kann sich nicht selbständig oder mit Hilfe von Dritten zum Standort des Ultraschallgerätes begeben.\r\n\r\nGilt nicht für Leistungen der Sparten: \r\n\r\n- Echokardiografie \r\n- Extrakorporale Stosswellen-Lithotripsie ({ESWL}) \r\n- Gastroenterologische Endoskopie, gross \r\n- Gastroenterologische Endoskopie, Spital \r\n- Gebärsaal \r\n- Urologische Funktionsdiagnostik \r\n- Urologischer Endoskopieraum',NULL,'K237ea20849f3c373022696',1511528425163,'0');
