INSERT INTO `TARMED_EXTENSION` VALUES ('00.0166-20180101-KVG',X'','Gilt für das Ausstellen von Rezepten oder Verordnungen ausserhalb von Konsultation, Besuch und telefonischer Konsultation in Abwesenheit des Patienten.\r\n\r\nAbrechenbar im Ausnahmefall bei Patienten über 6 Jahren und unter 75 Jahren mit einem erhöhten Behandlungsbedarf.\r\nDie Gründe für den erhöhten Behandlungsbedarf eines Patienten müssen in der Patientenakte aufgeführt werden. Der erhöhte Behandlungsbedarf eines Patienten ist gegenüber dem Versicherer zu begründen.\r\n\r\nGilt nicht für das Ausstellen von Rezepten oder Verordnungen, die in Zusammenhang mit der Erstellung von ärztlichen Zeugnissen, Berichten und Schreiben nach Kapitel [00.06], erbracht werden.\r\n\r\nMenge: gemäss Limitation in LG-11',NULL,'K379063bb0fa81d66084746',1511528316735,'0');
