INSERT INTO `TARMED_EXTENSION` VALUES ('34.0410-20070401',X'','Gilt nur für Patienten mit allogener Knochenmarktransplantation ({KMT}); siehe {KLV} 2.1, Anhang 1. \r\n\r\nBeispiele: akute Leukämien nach Induktionstherapie, chronisch-myeloische Leukämien, schwere aplastische Anämien, myelodysplastische Syndrome, maligne Lyphome und Thalassaemia major; bei der onkologischen Sterilpflegetechnik werden die Patienten unter strikter Sterilpflege behandelt; dies heisst, die Pflege erfolgt unter sterilen Lüftungsbedingungen, die Patienten erhalten sterile Nahrung, es besteht eine spezielle Vorrichtung für die Magen-Darm-Dekontamination und der Patient erhält sterile Gebrauchsgegenstände. \r\n\r\nZur Pflege/Untersuchung des Patienten muss sich das Personal steril umziehen; die im Zusammenhang mit der onkologischen Sterilpflege erforderlichen speziellen Massnahmen, Leistungen, Gebrauchsmaterialien und Verbrauchsmaterialien (bis zum Einkaufspreis (inkl. MWST) pro Einzelstück von CHF 3.--) sind mit der Tarifposition abgegolten und können demzufolge nicht separat abgerechnet werden; mit dieser Leistung sind auch die während eines Wechsels durchzuführenden Tätigkeiten (Zimmer und Möbel sterilisieren, Zimmer steril einrichten, Bett, Desinfektionsplatz usw.) abgegolten.',NULL,'kd35525f0b6a7cb35020517',1511528422024,'0');
