INSERT INTO `TARMED_EXTENSION` VALUES ('00.1390-20010101',X'','Mit der Tarifposition \"Feststellen des Todes\" durch den Facharzt werden abgerechnet:\r\n\r\n- Prüfung der Vitalfunktionen\r\n- Suche nach Todeszeichen\r\n- Suche nach Verletzungen, Injektionsmarken.\r\n\r\nMit den Tarifpositionen \"Konsultation\"/\"Besuch\" werden abgerechnet:\r\n\r\n- Erhebung der Fremdanamnese\r\n- Gespräche mit Angehörigen\r\n- allf. Lagerung des Toten.',NULL,'kfbad92901bd3f89a099567',1511528390187,'0');
