INSERT INTO `TARMED_EXTENSION` VALUES ('39.1305-20080101',X'','Die Voraussetzung für die Verrechnung muss gemäss KLV-Verordnung Art. 12e lit. c erfüllt sein.\r\n\r\nDie Verrechnung erfolgt nur mittels Pauschale, also keine Einzelverrechnung.\r\n\r\nDer administrative Aufwand zur Durchführung der Screeningprogramme ist in dieser Pauschale nicht enthalten.',NULL,'l32a5a24a314a1880021868',1511528424068,'0');
