INSERT INTO `TARMED_EXTENSION` VALUES ('24.0220-20010101-KVG',X'','Definition Exploration: Eingehende chirurgische Darstellung zur sicheren Beurteilung der im verletzten Gebiet betroffenen Strukturen (Sehnen, Gefässe, Nerven).\r\n\r\nDefinition komplex: Verletzung unübersichtlich, Verdacht auf Verletzung von Sehnen, Sehnenanhangsgebilden, Gefässen, Nerven; inkl. Débridement; inkl. Blutstillung. \r\n\r\nNicht verrechenbar, wenn das Verletzungsmuster aufgrund der klinischen u/o apparativen Untersuchung bereits vor dem Eingriff feststeht, z.B. bei Amputationen.\r\n\r\nDie Exploration und Therapieplanung ist zwingend im OP-Bericht zu dokumentieren.',NULL,'L3d82fe3d9d6315a0074148',1511528299996,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('37.0620-20141001',X'','Inkl. Material.',NULL,'L3d85881ac6217e91020948',1511528422680,'0');
