INSERT INTO `TARMED_EXTENSION` VALUES ('34.0110-20010101-KVG',X'','Die pflegerischen Leistungen kommen nur bei einem stationären Aufenthalt zur Anwendung. \r\n\r\nDie pflegerischen Leistungen {IPS} umfassen die Benutzung der Räumlichkeiten sowie der Geräte und Instrumente, die pflegerischen Tätigkeiten (Grundpflege und Behandlungspflege) inkl. Analysen, welche vom {IPS}-Personal mit den dort zur Verfügung stehenden Laborgeräten und Materialien vorgenommen werden können. \r\n\r\nDie diversen Tätigkeiten, z.B. Zeit für die Vor- und Nachbereitung der Beatmungsgeräte, Infusomaten, Injektionsgeräte und Überwachungsgeräte usw. sind in dieser Tarifposition einberechnet. \r\n\r\nBei jedem Eintritt in die {IPS} kann für die ersten 2 Std., unabhängig von der Patientenkategorie, diese Tarifposition abgerechnet werden. \r\n\r\nNach Ablauf der ersten 2 Std. wird der Patient in eine der 4 {SGI}-Pflegekategorien eingeteilt.',NULL,'l582d004f974f030081468',1511528311780,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('05.0790-20010101',X'',NULL,NULL,'L5b4e5939283181302398',1511528394529,'0');
