INSERT INTO `TARMED_EXTENSION` VALUES ('00.0417-20180101-KVG',X'','Abrechenbar im Ausnahmefall bei Patienten über 6 Jahren und unter 75 Jahren mit einem erhöhten Behandlungsbedarf.\r\n\r\nDie Gründe für den erhöhten Behandlungsbedarf eines Patienten müssen in der Patientenakte aufgeführt werden. Der erhöhte Behandlungsbedarf eines Patienten ist gegenüber dem Versicherer zu begründen.\r\n\r\nDie Leistung beinhaltet mindestens die folgenden Teile: \r\n\r\n - Gewicht und allenfalls Länge\r\n - orientierende Allgemeinbeurteilung\r\n - Haut kursorisch, Mund/Zähne, Rachen/Hals, Trommelfell (Kind)\r\n - physikalische Untersuchung der Thoraxorgane\r\n - Puls, Blutdruck (Erwachsene)\r\n - physikalische Untersuchung des Abdomens',NULL,'mcbc397da5ec3a5a1084775',1511528316767,'0');
