INSERT INTO `TARMED_EXTENSION` VALUES ('24.0220-20010101',X'','Definition Exploration: Eingehende chirurgische Darstellung zur sicheren Beurteilung der im verletzten Gebiet betroffenen Strukturen (Sehnen, Gefässe, Nerven).\r\n\r\nDefinition komplex: Verletzung unübersichtlich, Verdacht auf Verletzung von Sehnen, Sehnenanhangsgebilden, Gefässen, Nerven; inkl. Débridement; inkl. Blutstillung. \r\n\r\nNicht verrechenbar, wenn das Verletzungsmuster aufgrund der klinischen u/o apparativen Untersuchung bereits vor dem Eingriff feststeht, z.B. bei Amputationen.\r\n\r\nDie Exploration und Therapieplanung ist zwingend im OP-Bericht zu dokumentieren.',NULL,'Me9438783913582d9013144',1511528410645,'0');
