INSERT INTO `TARMED_EXTENSION` VALUES ('00.1390-20180101-KVG',X'','Mit der Tarifposition \"Feststellen des Todes\" durch den Facharzt werden abgerechnet:\r\n\r\n- Prüfung der Vitalfunktionen\r\n- Suche nach Todeszeichen\r\n- Suche nach Verletzungen, Injektionsmarken.\r\n\r\nMit den Tarifpositionen \"Konsultation\"/\"Besuch\" werden abgerechnet:\r\n\r\n- Erhebung der Fremdanamnese\r\n- Gespräche mit Angehörigen\r\n- allf. Lagerung des Toten.',NULL,'Meaf34865c9e52cf6085094',1511528317192,'0');
