INSERT INTO `TARMED_EXTENSION` VALUES ('39.1306-20090301',X'','Die Voraussetzung für die Verrechnung muss gemäss KLV-Verordnung Art. 12e lit. c erfüllt sein.\r\n\r\nDie Verrechnung erfolgt nur mittels Pauschale, also keine Einzelverrechnung.\r\n\r\nDer administrative Aufwand zur Durchführung der Screeningprogramme ist in dieser Pauschale nicht enthalten.',NULL,'n86ddafa90d4287c021874',1511528424079,'0');
