INSERT INTO `TARMED_EXTENSION` VALUES ('28.0010-20070401-KVG',X'','Monitored Anesthesia Care (MAC):\r\n\r\nÜberwachung mit oder ohne Sedation und/oder Analgesie auf Verlangen des behandelnden Facharztes bei Eingriffen und diagnostischen Massnahmen mit und ohne vom behandelnden Facharzt gesetzten Lokalanästhesien.\r\n\r\nVoraussetzungen:\r\n\r\n- Perioperative Betreuung durch den Anästhesisten\r\n- Der Anästhesist befindet sich während des Eingriffes/der Massnahme am Patienten und überwacht diesen.\r\n- Der Patient bleibt auf Ansprache weckbar und seine Spontanatmung ohne mechanische Unterstützung suffizient.\r\n\r\nDie perioperative Betreuung beinhaltet:\r\n\r\n- Prämedikation am Vortag oder am Operationstag mit persönlicher Visite des Anästhesisten, allenfalls auch ambulant vorgezogen. \r\n- Postoperative ärztliche Behandlung am Operationstag in der Aufwachstation oder auf der Krankenabteilung bis zum Arbeitsbeginn des nächsten Tages u/o bei {IPS}-Patienten bis eine Stunde nach Operationsende.',NULL,'Oc4bd8049012e7fb0078097',1511528306490,'0');
