INSERT INTO `TARMED_EXTENSION` VALUES ('24.0250-20180101-KVG',X'','Zuschlag von 15% ({AL} und {TL}) auf die Tarifpositionen Versorgung/Reposition von Frakturen/Luxationen.\r\n\r\nLeistungsinhalt: Mehraufwand bei Versorgung einer offenen Fraktur/Luxation, insbesondere allf. Wundversorgung (Débridement/Auffrischen, Entfernen von Schmutz/Fremdkörpern, Wundspülung, lokale Applikation von Medikamenten, allf. Drainage).\r\n\r\nSiehe {26}, Versorgung offener Frakturen/Luxationen.',NULL,'P1e1553cf9132f386093449',1511528330075,'0');
