INSERT INTO `TARMED_EXTENSION` VALUES ('00.0060-20120601-KVG',X'','Beinhaltet alle ärztlichen Leistungen, die der Facharzt ausserhalb seiner Praxis ohne oder mit einfachen Hilfsmitteln (etwa Inhalt Besuchskoffer) am Patienten hinsichtlich der Beschwerden und Erscheinungen erbringt, derentwegen dieser zum Facharzt kommt, bzw. gebracht wird und hinsichtlich der Beschwerden und Erscheinungen, die während der gleichen Behandlungsdauer auftreten.\r\n\r\nGilt für alle Arten von Besuchen (zuhause, an der Unfallstelle usw.), ausgenommen sind Behandlungen im Spital (ambulante und/oder stationäre Patienten).\r\n\r\nDer Weg von der Praxis zum Patienten und zurück ist Gegenstand der Tarifposition Wegentschädigung (00.0095).\r\n\r\nDie für den Besuch massgebende Zeit beginnt beim Eintreffen des Facharztes beim Patienten.',NULL,'p3e986d50e5fa9a48060109',1511528277599,'0');
