INSERT INTO `TARMED_EXTENSION` VALUES ('00.2420-20010101-KVG',X'','Für ausserordentlich schwierige Fälle sind Spezialabmachungen mit dem Auftraggeber zu treffen. Unter diese Kategorie gehören: ausserordentlich aufwändiges Aktenstudium, hohe Schwierigkeit der gutachterlichen Überlegungen und Schlussfolgerungen, ausserordentlich schwieriges Verfassen des Gutachtens mit ungewöhnlich umfangreichen Recherchen.\r\n\r\nAbrechnung gemäss spezieller Vereinbarung mit dem Kostenträger.',NULL,'pc4fe199071b40393060909',1511528279098,'0');
