INSERT INTO `TARMED_EXTENSION` VALUES ('28.0210-20010101',X'','Gilt ausschliesslich für therapeutische Massnahmen bei einem Herzkreislaufstillstand. \r\n\r\nBeinhaltet Herzmassage, Defibrillation, Intubation und Beatmung; inkl. anschliessende Vorbereitung des Patienten zur Verlegung oder für eine weitere Behandlung. \r\n\r\nNicht abrechenbar in der {IPS}, Verbrennungs-{IPS}, {IPS} Neonatologie, Intermediate Care, im Operationssaal und anlässlich einer Anästhesie.',NULL,'Pd272a30da5c80df9017199',1511528416975,'0');
