INSERT INTO `TARMED_EXTENSION` VALUES ('37.0330-20180101-KVG',X'','Inkl. mikroskopischer Beschreibung, Beurteilung mit Diagnose und Kommentar zur Befundung und zur klinischen Fragestellung, inkl. Auswertung von Spezialfärbungen, Spezialuntersuchungen. \r\n\r\nBeispiele: Zellveränderungen mit komplexer Differentialdiagnose, Vergleich mit Vorbefunden unumgänglich; Auswertung von Spezialfärbungen, Spezialuntersuchungen; Nachweis eines speziellen Erregers.',NULL,'pd360133519991555095909',1511528334119,'0');
