INSERT INTO `TARMED_EXTENSION` VALUES ('24.4820-20010101-KVG',X'','Primäres Einsetzen einer Hüftgelenkkomponente oder einer Pfanne oder einer Femurkomponente. \r\n\r\nGilt nicht für Wechsel eines künstlichen Gelenkkopfes oder einer künstlichen Gelenkpfanne. \r\n\r\nGilt auch für Umwandlung einer Kopfprothese in eine Totalprothese; inkl. allf. Knochenplastik, Cerclage, Fixation Trochanter maior.\r\n\r\nInkl. allf. Knochenplastik, Cerclage, Fixation Trochanter maior.',NULL,'qf59aa328e5436453075900',1511528303040,'0');
