INSERT INTO `TARMED_EXTENSION` VALUES ('00.0056-20180101-KVG',X'','Abrechenbar im Ausnahmefall bei Patienten über 6 Jahren und unter 75 Jahren mit einem erhöhten Behandlungsbedarf.\r\n\r\nDie Gründe für den erhöhten Behandlungsbedarf eines Patienten müssen in der Patientenakte aufgeführt werden. Der erhöhte Behandlungsbedarf eines Patienten ist gegenüber dem Versicherer zu begründen.\r\n\r\nBesprechen und erklären geplanter Eingriffe (Ablauf, Chancen und Risiken) inkl. adäquater Dokumentation der erfolgten Patienteninformation.',NULL,'R1959062983fe05c4084633',1511528316586,'0');
