INSERT INTO `TARMED_EXTENSION` VALUES ('07.0300-20180101-KVG',X'','Zuschlag von 45% ({AL} und {TL}) zu der entsprechenden Hauptleistung, nach der - mit oder ohne Osteosynthese - ein unvollständiger knöcherner Durchbau u/o eine pseudarthrotische Fraktur im Gesichtsschädel aufgetreten ist.\r\n\r\nSog. delayed union.',NULL,'r65e8bc195d0300d087653',1511528321073,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('37.0230-20180101-KVG',X'','Inkl. Protokollierung der makroskopischen Befunde und Probenentnahme für Histologie. \r\n\r\nBeispiele: Präparieren, Beurteilen und Zuschneiden von grossen Resektaten, meist wegen einer Neoplasie wie Pneumonektomie, Mammaamputat mit Axilla, radikales Prostatektomiepräparat mit Lymphknoten, Kolonresektate mit Lymphknoten.\r\n\r\nMax. 1 x pro Topografie/Lokalisation abrechenbar, unabhängig von der Anzahl Proben.',NULL,'R6670df3bc159d26095883',1511528334074,'0');
