INSERT INTO `TARMED_EXTENSION` VALUES ('04.2580-20141001',X'','Beinhaltet Präparation und Débridement sowie Vereinigung des proximalen und distalen Stumpfes; inkl. allf. Muskelnähte.\r\n\r\nGilt auch bei noch bestehender, alleiniger Weichteilbrücke.\r\n\r\nGefässnähte (04.2620) und Nervennähte (04.0810).\r\n\r\nGefässtransplantate ((04.1690) ff) und Nerventransplantate ((04.1730) ff).\r\n\r\nOsteosynthesen [24.03.07.01].\r\n\r\nSehnennähte (04.0720).',NULL,'Rcc7c42207941712001633',1511528393430,'0');
