INSERT INTO `TARMED_EXTENSION` VALUES ('00.0060-20010101',X'','Beinhaltet alle ärztlichen Leistungen, die der Facharzt ausserhalb seiner Praxis ohne oder mit einfachen Hilfsmitteln (etwa Inhalt Besuchskoffer) am Patienten hinsichtlich der Beschwerden und Erscheinungen erbringt, derentwegen dieser zum Facharzt kommt, bzw. gebracht wird und hinsichtlich der Beschwerden und Erscheinungen, die während der gleichen Behandlungsdauer auftreten.\r\n\r\nGilt für alle Arten von Besuchen (zuhause, an der Unfallstelle usw.), ausgenommen sind Behandlungen im Spital (ambulante und/oder stationäre Patienten), siehe Kapitel [00.01.02].\r\n\r\nDer Weg von der Praxis zum Patienten und zurück ist Gegenstand der Tarifposition Wegentschädigung (00.0095).\r\n\r\nDie für den Besuch massgebende Zeit beginnt beim Eintreffen des Facharztes beim Patienten.',NULL,'s1b9e6080bcdc5cdb099161',1511528389655,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('22.0040-20010101-KVG',X'','Spezifische persönliche und familiäre Anamnese inkl. Partner; Besprechung Anamnese und Befund mit Patientin und eventuell mit Partner; Darlegen möglicher Ursachen. \r\n\r\nAufzeigen von diagnostischen und therapeutischen Möglichkeiten, inkl. Chancen und Risiken.',NULL,'s1ba07ec9c769bb7a072961',1511528298334,'0');
