INSERT INTO `TARMED_EXTENSION` VALUES ('37.0260-20010101',X'','Inkl. Auswertung von Spezialfärbungen und Spezialmethoden sowie Konsultation von Standardwerken.\r\n\r\nBeispiele: Resektate mit mehreren Lymphknotenstationen, Präparate mit zahlreichen Stufenschnitten, Präparate mit Immunohistochemie.\r\n\r\nMax. 1 x pro Topografie/Lokalisation abrechenbar, unabhängig von der Anzahl Proben.',NULL,'s3ef3ac660eb4cea4020811',1511528422462,'0');
