INSERT INTO `TARMED_EXTENSION` VALUES ('35.0510-20070401-KVG',X'','Die Position beinhaltet die nichtärztliche Betreuung von Patienten ausserhalb der Tagesklinik. \r\n\r\nNur verrechenbar bei medizinisch bedingtem Aufenthalt. \r\n\r\nGilt nicht für organisatorisch verursachte Wartezeiten.\r\n\r\nDie Tarifposition beinhaltet folgende Tätigkeiten durch nichtärztliches Personal: \r\n\r\n- Aufnahme des Patienten auf der Abteilung\r\n- Information und Anweisungen an den Patienten\r\n- Medikation und Wundpflege\r\n- Überwachung und Pflege bis zum Austritt\r\n\r\nInkl. Bettbenützung, Mahlzeiten und Getränke usw..\r\n\r\nGilt auch für die Betreuung/Überwachung vor und nach Behandlung in der allgemeinen Schmerztherapie sowohl im Spital als auch in der Arztpraxis.',NULL,'sca4e9cc7788c3b8e081661',1511528312072,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('08.2600-20141001',X'',NULL,NULL,'sca7d5ca67f6c672a05361',1511528398748,'0');
