INSERT INTO `TARMED_EXTENSION` VALUES ('04.0186-20141001',X'','Diese Untersuchung bleibt der Diagnostik und der Überwachung der Malignität der Körpermale bei Patienten mit persönlicher oder familiärer Vordisposition für Melanome, Trägern von mehr als 50 Schönheitsmalen oder Trägern des dysplastischen Naevus-Syndrom vorbehalten.\r\nSie beinhaltet die Erstellung einer digitalisierten Bilddokumentation mit hoher Auflösung der suspekten Körpermale, unabhängig von deren Anzahl.',NULL,'sd87b6d00e525235d0511',1511528391737,'0');
