INSERT INTO `TARMED_EXTENSION` VALUES ('04.2530-20010101-KVG',X'','Beinhaltet Präparation und Débridement sowie Vereinigung des proximalen und distalen Stumpfes; inkl. allf. Muskelnähte.\r\n\r\nGilt auch bei noch bestehender, alleiniger Weichteilbrücke.\r\n\r\nGefässnähte (04.2620) und Nervennähte (04.0800) und (04.0810).\r\n\r\nGefässtransplantate ((04.1690) ff) und Nerventransplantate ((04.1730) ff).\r\n\r\nOsteosynthesen [07] und [10].\r\n\r\nSehnennähte (04.0720).',NULL,'seaa19a675963f697062611',1511528282003,'0');
