INSERT INTO `TARMED_EXTENSION` VALUES ('35.0210-20141001-KVG',X'','Gilt nur bei Behandlung ambulanter und somatischer Tagesklinikpatienten. \r\n\r\nDie Tarifposition beinhaltet folgende Tätigkeiten durch nichtärztliches Personal: Operationsvorbereitung, Prämedikation, Information und Anweisungen an den Patienten, Medikation und Wundpflege, Überwachung und Pflege bis zum Austritt; inkl. Bettbenützung, Mahlzeiten und Getränke usw.. \r\n\r\nGrundsätzlich kann die nichtärztliche Betreuung nur bis zur Stabilisierung aller vitalen Funktionen verrechnet werden, nämlich: Erlangen des Bewusstseins, normale(r) Atmung und Kreislauf, Schmerzempfindung und Beweglichkeit usw.; gilt auch für somatische postinterventionelle Betreuung, internistische Überwachung, sowie intubierte Patienten.\r\n\r\nGilt auch für die Betreuung/Überwachung vor und nach ambulanten Eingriffen in gemäss Spartenkonzept anerkannten Operationssälen und der interventionellen Schmerztherapie sowohl im Spital als auch in der Arztpraxis.',NULL,'T34f4fd79cf3bd7dd081636',1511528312036,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('00.0460-20090301',X'','Gilt für Lebendspender von Niere, Leberlappen, Pankreasinseln oder Stammzellen.\r\n\r\nBeinhaltet die vollständige Untersuchung der Routinekontrolle wie:\r\n\r\n- Befragung des Spenders (Befinden, Beschwerden)\r\n- Teilstatus mit Gewicht und Blutdruck\r\n- Urin-Streifentest (Blut, Leukozyten, Glucose)\r\n- ein Urinsediment (nur bei positivem Befund)\r\n\r\nZusätzlich sind gemäss der Analysenliste mit Tarif (AL) verrechenbar:\r\n\r\n- 1020.00 Alanin-Aminotransferase (ALAT) \r\n- 1021.00 Albumin, chemisch \r\n- 1093.00 Aspartat-Aminotransferase (ASAT) \r\n- 1207.00 Bilirubin, gesamt \r\n- 1371.00 Hämatogramm II (automatisiert: Hämatogramm I, plus Thrombozyten \r\n- 1509.00 Kreatinin, im Blut/Plasma/Serum \r\n- 1510.00 Kreatinin, in einer weiteren Körperflüssigkeit \r\n- 1700.00 Thromboplastinzeit nach Quick \r\n- 1739.00 Urinstatus (5-10 Parameter und mikroskopische oder flowzytometrische Bestimmung der korpuskulären Urinbestandteile) \r\n- 1740.00 Urin-Teilstatus (5-10 Parameter)',NULL,'t350ef5e2e2c3c8c3099304',1511528389818,'0');
