INSERT INTO `TARMED_EXTENSION` VALUES ('15.0730-20180101-KVG',X'','Leistungsinhalt:\r\n\r\nKontinuierliche Aufzeichnung von\r\n- Sauerstoffsättigung\r\n- Herzfrequenz\r\n- Atmungstätigkeit (jede Methode)\r\n- Schlaf ({EEG}, {EOG})\r\n- Bewegung und Lage ({EMG}, Aktigrafie).\r\n\r\nInkl. Elektrokardiografie, Videografie, Audiografie und allf. weitere Parameter.\r\n\r\nAllf. ärztliche Beobachtung während der Leistung, Überwachung durch im Schlaflabor anwesende Person.\r\n\r\nDauer mindestens 6 Stunden.\r\n\r\nInkl. obligate, integrative - allenfalls interdisziplinäre - Gesamtbeurteilung.',NULL,'Teae5925372d29b36089786',1511528324445,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('04.1080-20180101-KVG',X'','Wundversorgung beinhaltet: \r\n\r\n- Débridement/Auffrischen Wundrand und Wundgrund\r\n- Entfernen von Schmutz/Fremdkörpern\r\n- Wundspülung\r\n- Wundrandmobilisierung\r\n- Glatter und spannungsfreier Wundverschluss (Direktverschluss)\r\n- allf. Drainage.\r\n\r\nBei traumatischer Gelenkeröffnung kann die entsprechende Arthrotomietarifposition verrechnet werden.',NULL,'Teaea587373bdbb44086086',1511528318682,'0');
