INSERT INTO `TARMED_EXTENSION` VALUES ('36.0030-20010101-KVG',X'','Die pflegerischen Leistungen umfassen die Überwachung und die Betreuung des Notfallpatienten wie z.B. Kontrolle des Allgemeinzustandes (Bewusstsein, Blutdruck, Puls, Pupillenreaktionen, Zentralvenendruck usw.); Dokumentationen, Instruktionen usw.. \r\n\r\nDie Tarifposition darf nicht mehr abgerechnet werden, sobald der Patient die Notfallaufnahme definitiv verlässt (Austritt oder Verlegung); organisatorisch bedingte Wartezeiten können nicht abgerechnet werden. \r\n\r\nWird der Patient im Anschluss an die ärztliche Leistung hospitalisiert, kann diese Tarifposition nicht abgerechnet werden; diese Tarifposition kann nur solange abgerechnet werden, als keine anderen Leistungen ausserhalb Kapitel [36] erbracht werden.',NULL,'Tee611e1a281defc4081686',1511528312105,'0');
