INSERT INTO `TARMED_EXTENSION` VALUES ('32.0650-20141001',X'','Therapie mit adaptiertem/dediziertem Bestrahlungsgerät.\r\n\r\nBeinhaltet Überprüfung der Indikation, Festlegung des Untersuchungsganges, Weisungen und Erklärungen an Fachpersonal und Patienten. {TL} und {AL} beinhalten abschliessend die Aktivitäten zur\r\n\r\n1. Vorbereitung: {CT}/{MRI} Grundleistungen, {OP}-Benützung, Zielpunktbestimmung mit Anlegen des Rahmens, allfällige Anästhesieleistungen in der Vorbereitung.\r\n\r\n2. Bestrahlungsphase: Die Planung und die Einmalbestrahlung.\r\n\r\nAm Bestrahlungstag sind somit keine weiteren Aufnahmen im Schädel-Hirnbereich mit {CT} oder {MRI} möglich. Nicht inbegriffen sind Leistungen der Tagesklinik.',NULL,'u19c5d2953362a047020056',1511528421350,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('39.0500-20180101-KVG',X'','Als Regionen gelten die in der KI-[39-14] aufgeführten Gelenksregionen.\r\n \r\nWerden bei einer Untersuchung einer Region mehrere Gelenke durchleuchtet, kann diese Tarifposition nur einmal abgerechnet werden.\r\n \r\nBeinhaltet auch Atlantooccipital-Gelenk und Atlantodental-Gelenk.',NULL,'u19e4079741d558b9096206',1511528334571,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('18.0220-20070401',X'',NULL,NULL,'U19e7e7785e713b8a08242',1511528403519,'0');
