INSERT INTO `TARMED_EXTENSION` VALUES ('00.2315-20070401-KVG',X'','Die Höhe des Expresszuschlags wird im Hinblick auf einen festgelegten Ablieferungstermin zwischen Auftraggeber und Auftragnehmer vereinbart. \r\n\r\nEr kann vom Auftragnehmer in Rechnung gestellt werden, falls die Terminvorgabe eingehalten wird. \r\n\r\nDie Tarifposition setzt sich nur aus einer ärztlichen Leistung ({AL}) zusammen. \r\n\r\nDie Anwendung bleibt besonderen Fällen vorbehalten; die Ausrichtung eines Expresszuschlags kann, wenn eine solche bei der Auftragerteilung nicht ausdrücklich vereinbart worden ist, nicht nachträglich eingefordert werden.\r\n\r\nAbrechnung gemäss spezieller Vereinbarung mit dem Kostenträger.',NULL,'Uc30a134b1851cb87060842',1511528278969,'0');
