INSERT INTO `TARMED_EXTENSION` VALUES ('36.0120-20010101-KVG',X'','Die Tarifposition kann in Ausnahmefällen von einer Klinik ohne Notfallversorgungsauftrag abgerechnet werden. \r\n\r\nDie pflegerischen Leistungen kommen nur bei Notfallpatienten zur Anwendung. \r\n\r\nEin Notfallpatient wird definiert als Patient einer Klinik, bei dem ein verzugsloses Handeln durch ärztliches und nichtärztliches Personal aus medizinischen Gründen erforderlich ist. Die pflegerischen Leistungen umfassen Patiententriage (z.B. Abklärung bezüglich Dringlichkeit und Behandlungsbedürftigkeit); Informationen weiterleiten oder einholen (Patient, Angehörige, andere Ansprechpartner); Beschaffung von Patientendaten (Krankengeschichte, Versicherung, externe Berichte usw.). \r\n\r\nOrganisation von Arbeitsabläufen, Weiterbehandlungen, diverse Untersuchungen usw.; Patientenvorbereitung für weitere Behandlungen (z.B. ausziehen, waschen, prämedizieren usw.). \r\n\r\nMit dieser Leistung sind auch die während eines Wechsels durchzuführenden Tätigkeiten (Vorbereitung der Apparaturen, Messgeräte usw.,  Bereitstellen von Liegen, Aufräumarbeiten und Reinigungsarbeiten, Medikamentenbestellung und Materialbestellungen usw.) enthalten. \r\n\r\nWird der Patient im Anschluss an die ärztliche Leistung hospitalisiert, kann diese Tarifposition nicht abgerechnet werden; diese Tarifposition kann nur solange abgerechnet werden, als keine anderen Leistungen ausserhalb Kapitel [36] erbracht werden.',NULL,'Ue04d6ce937493bbf081692',1511528312116,'0');
