INSERT INTO `TARMED_EXTENSION` VALUES ('24.0220-20180101-KVG',X'','Definition Exploration: Eingehende chirurgische Darstellung zur sicheren Beurteilung der im verletzten Gebiet betroffenen Strukturen (Sehnen, Gefässe, Nerven).\r\n\r\nDefinition komplex: Verletzung unübersichtlich, Verdacht auf Verletzung von Sehnen, Sehnenanhangsgebilden, Gefässen, Nerven; inkl. Débridement; inkl. Blutstillung. \r\n\r\nNicht verrechenbar, wenn das Verletzungsmuster aufgrund der klinischen u/o apparativen Untersuchung bereits vor dem Eingriff feststeht, z.B. bei Amputationen.\r\n\r\nDie Exploration und Therapieplanung ist zwingend im OP-Bericht zu dokumentieren.',NULL,'Uf92c328b657b74b093442',1511528330061,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('39.2000-20080101',X'','Diese Tarifposition darf nur bei einer erneuten zweiten Zuweisung am gleichen Tag ein zweites Mal abgerechnet werden.',NULL,'uf940bd7996659c56021956',1511528424202,'0');
