INSERT INTO `TARMED_EXTENSION` VALUES ('35.0110-20141001',X'','Postoperative (inkl. apparativer) Überwachung stationärer Patienten bis zur Stabilisation der vitalen Funktionen: Allgemeinzustand, Bewusstsein, Blutdruck, Puls, Pupillenreaktion, Zentralvenendruck.\r\n\r\nMedikation: Injektionen, Infusionen und Bluttransfusionen usw. \r\n\r\nBehandlung: Absaugen oral/nasal, {O2}-Verabreichung, Drainage/Spülung, Verbandwechsel, Dokumentation, Patientenübergabe, Instruktionen usw.\r\n\r\nGilt nur bei stationärer Behandlung in separatem, zweckgebundenen, an den {OP}-Bereich angegliederten Aufwachraum.',NULL,'Ufab138d51145fb51020592',1511528422135,'0');
