INSERT INTO `TARMED_EXTENSION` VALUES ('28.0150-20010101-KVG',X'','Als Anästhesiezeit gilt die im Tarif festgelegte Zeit für die Leistung im engeren Sinne und die Zeit für Vor- und Nachbereitung. \r\n\r\nBei Tarifpositionen ohne festgelegte Zeit für die Leistung im engeren Sinne, gilt die Schnitt-Naht-Zeit bei operativen Eingriffen bzw. die Untersuchungszeit gemäss Anästhesieblatt bei diagnostischen Eingriffen; bei Mehrfacheingriffen gelten die in den Tarifpositionen aufgeführten Risikoklassen. \r\n\r\nAnästhesieleistung mit stark erhöhtem Risiko:\r\n\r\n- Laparotomien (ausgenommen Appendektomie )\r\n- Thorakotomien\r\n- Lumbotomien\r\n- Kraniotomien\r\n- Wirbelsäulenoperationen\r\n- laparoskopische, thorakoskopische Eingriffe\r\n- maxilläre, rhinologische, orale, pharyngeale, laryngologische Eingriffe\r\n- Endoskopien über Mund/Nase\r\n- Kinder bis zu 2 Jahren (ausgenommen operative Versorgung Risikoklasse IV).\r\n\r\nBei einer Schnellschnittuntersuchung können für intraoperatives Warten 1 x pro Eingriff 35 Min. zusätzlich zur tarifarischen Leistung im engeren Sinne und Vor- und Nachbereitung abgerechnet werden.',NULL,'Vcb19ea1402804f88078185',1511528306615,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('24.3266-20180101-KVG',X'',NULL,NULL,'vcb1c69e3008f51a1094022',1511528331066,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('04.1030-20070401-KVG',X'','Wundversorgung beinhaltet:\r\n\r\n- Débridement/Auffrischen Wundrand und Wundgrund\r\n- Entfernen von Schmutz/Fremdkörpern\r\n- Wundspülung\r\n- Wundrandmobilisierung\r\n- Glatter und spannungsfreier Wundverschluss (Direktverschluss)\r\n- allf. Drainage.\r\n\r\nKomplexe Strukturen: siehe KI-[04.02.02-1].',NULL,'Vcb274197d3e0d863062035',1511528280968,'0');
