INSERT INTO `TARMED_EXTENSION` VALUES ('28.0060-20010101-KVG',X'','Bei Mehrfacheingriffen kommt die höher verrechenbare Risikoklasse zur Anwendung. \r\n\r\nDie perioperative Betreuung beinhaltet: Prämedikation am Vortag oder am Operationstag mit persönlicher Visite des Anästhesisten, allenfalls auch ambulant vorgezogen; postoperative ärztliche Behandlung am Operationstag in der Aufwachstation oder auf der Krankenabteilung bis zum Arbeitsbeginn des nächsten Tages u/o bei {IPS}-Patienten bis eine Stunde nach Operationsende.\r\n\r\nAnästhesieleistung mit sehr hohem Risiko: operative Versorgung am Herzen und thorakalen grossen Gefässen, kombinierte thorakoabdominale operative Versorgung und abdominelle Aorta, grössere operative Versorgung im Bereich des zentralen Nervensystems (cerebrale Tumoren, Hirnbasisaneurysmata).',NULL,'W1763298d344c4fa5078129',1511528306531,'0');
