INSERT INTO `TARMED_EXTENSION` VALUES ('28.0140-20070401',X'','Als Anästhesiezeit gilt die im Tarif festgelegte Zeit für die Leistung im engeren Sinne und die Zeit für Vor- und Nachbereitung. \r\n\r\nBei Tarifpositionen ohne festgelegte Zeit für die Leistung im engeren Sinne, gilt die Schnitt-Naht-Zeit bei operativen Eingriffen bzw. die Untersuchungszeit gemäss Anästhesieblatt bei diagnostischen Eingriffen; bei Mehrfacheingriffen gelten die in den Tarifpositionen aufgeführten Risikoklassen.\r\n\r\nAnästhesieleistung mit erhöhtem Risiko; Operation in Bauchlage; ophthalmologische, otologische, urologische Operationen (ohne Operationen am äusseren Genitale sowie an Nebennieren, Nieren, Nierenbecken und Ureteren); vaginale und geburtshilfliche operative Versorgung, (Ausnahmen siehe Risikoklasse I und Risikoklasse III), operative Versorgung an Gesicht, Hals, Schultergürtel; grössere orthopädische Operationen (Hüftgelenk, Kniegelenkendoprothesen).\r\n\r\nKinder bis 2 Jahren Risikoklasse III. \r\n\r\nBei einer Schnellschnittuntersuchung können für intraoperatives Warten 1 x pro Eingriff 35 Min. zusätzlich zur tarifarischen Leistung im engeren Sinne und Vor- und Nachbereitung abgerechnet werden.',NULL,'W1e05ab08748ed246017179',1511528416938,'0');
