INSERT INTO `TARMED_EXTENSION` VALUES ('03.0135-20090301-KVG',X'','Entwicklungspädiatrische Untersuchung, inkl. Auswertung der verwendeten diagnostischen Tests: z.B. bei Gedeihstörung, Essstörung, Schreiverhalten, Schlafstörung, Störung der Autonomieentwicklung, Störung des Sozialverhaltens, Sprachentwicklungsstörung, Störungen des Antriebes, der Wahrnehmung, der Merkfähigkeit, etc.\r\n\r\nEin vermehrter Zeitaufwand muss gegenüber dem Vertrauensarzt begründet werden. \r\n\r\nDarf nur von nicht vom Spital fix besoldeten Fachärzten abgerechnet werden.',NULL,'W342b39813833a1e061329',1511528279820,'0');
