INSERT INTO `TARMED_EXTENSION` VALUES ('00.2510-20180101-KVG',X'','Notfallkriterien Tag (tarifarisch):\r\n \r\n- Bei direktem Arzt - Patientenkontakt: Jeder Patient, bei dem sich unabhängig von der auslösenden Ursache eine Störung der vitalen Funktionen ausbildet, zu befürchten, respektive nicht auszuschliessen ist. Gilt auch für Patienten bei denen eine akute Erkrankung, ein Trauma oder eine Vergiftung eine Organschädigung hervorrufen oder zur Folge haben kann. Im Bereich der Psychiatrie ist von einem Notfall auszugehen bei Erregungszuständen, Selbst- und Fremdgefährdung, Bewusstseinsstörungen sowie kataton-stuporösen Zuständen.\r\n\r\n- Ohne direkten Arzt - Patientenkontakt: Medizinisch notwendig und/oder vom Patienten, Angehörigen oder Dritten als offensichtlich notwendig erachtet\r\n \r\n- Der Facharzt befasst sich sofort, verzugslos mit dem Patienten bzw. sucht ihn auf. \r\n \r\n- Es wird ein unmittelbarer Arzt - Patienten - Kontakt vorausgesetzt. Ausnahme: Vergebliche Fahrt zum Unfallort/Ereignisort.\r\n \r\n- Besuche: zuhause, Alters- und Pflegeheim, Unfallort, Ereignisort usw..\r\n  \r\nFür die Entschädigung massgebend ist der Zeitpunkt des ersten, direkten und unmittelbaren Arzt - Patienten - Kontakts (Ausnahme: Bei Notfallbesuch gilt die Startzeit).\r\n  \r\nDarf nur von nicht vom Spital oder Institut fix besoldeten Fachärzten abgerechnet werden.\r\n  \r\nBei Einsätzen im Spital oder Institut gilt:\r\n \r\nDer Facharzt begibt sich für den ungeplanten, notfallmässigen Einsatz von ausserhalb ins Spital oder Institut. Hiermit abgegolten ist auch die Wegentschädigung. Fachärzte, welche vom Spital oder Institut ganz oder teilweise fix besoldet sind, haben kein Anrecht auf Verrechnung dieser Tarifposition.',NULL,'W3b9cd66255e11061085379',1511528317634,'0');
