INSERT INTO `TARMED_EXTENSION` VALUES ('50.0010-20040401-KVG',X'','Als anrechenbare Zeit gilt die im Tarif festgelegte Zeit für die Leistung im engeren Sinne, für Vor- und Nachbereitung und Bericht.\r\n\r\nGilt nur für Operationen/Interventionen im Spital an ambulanten oder stationären Patienten durch den nicht vom Spital fix besoldeten Belegarzt, der dem Vertrag zwischen der {MTK}/{MV}/{IV} und der {FMH}/{SBV} beigetreten ist.','Nur am Tag der Operation/Intervention abrechenbar.\r\n\r\n(00.0210) ist mit (50.0010) pro Fall nur 1 Mal verrechenbar.\r\n\r\n(00.0310) ist mit (50.0010) am ersten Hospitalisationstag max. 4 Mal verrechenbar, an den darauf folgenden Hospitalisationstagen bis zum Austrittstag maximal 2 Mal pro Tag.','W698381b8bf69d8084579',1511528316520,'0');
