INSERT INTO `TARMED_EXTENSION` VALUES ('30.5210-20070401-KVG',X'','Beinhaltet Überprüfung Indikation, Festlegung des Untersuchungsganges, Weisungen und Erklärungen an Fachpersonal und Patienten; inkl. Lokalisationsaufnahmen (Topogramm).',NULL,'Wc3ee4c4b2affdbd6079779',1511528309154,'0');
