INSERT INTO `TARMED_EXTENSION` VALUES ('34.0110-20010101',X'','Die pflegerischen Leistungen kommen nur bei einem stationären Aufenthalt zur Anwendung. \r\n\r\nDie pflegerischen Leistungen {IPS} umfassen die Benutzung der Räumlichkeiten sowie der Geräte und Instrumente, die pflegerischen Tätigkeiten (Grundpflege und Behandlungspflege) inkl. Analysen, welche vom {IPS}-Personal mit den dort zur Verfügung stehenden Laborgeräten und Materialien vorgenommen werden können. \r\n\r\nDie diversen Tätigkeiten, z.B. Zeit für die Vor- und Nachbereitung der Beatmungsgeräte, Infusomaten, Injektionsgeräte und Überwachungsgeräte usw. sind in dieser Tarifposition einberechnet. \r\n\r\nBei jedem Eintritt in die {IPS} kann für die ersten 2 Std., unabhängig von der Patientenkategorie, diese Tarifposition abgerechnet werden. \r\n\r\nNach Ablauf der ersten 2 Std. wird der Patient in eine der 4 {SGI}-Pflegekategorien eingeteilt.',NULL,'wc47444a84cc38f020451',1511528421931,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('28.0090-20010101',X'','Bei Mehrfacheingriffen kommt die höher verrechenbare Risikoklasse zur Anwendung. \r\n\r\nAnästhesieleistung mit erhöhtem Risiko; Operation in Bauchlage; ophthalmologische, otologische, urologische Operationen (ohne Operationen am äusseren Genitale sowie an Nebennieren, Nieren, Nierenbecken und Ureteren); vaginale und geburtshilfliche operative Versorgung (Ausnahmen siehe Risikoklasse I und Risikoklasse III), operative Versorgung an Gesicht, Hals, Schultergürtel; grössere orthopädische Operationen (Hüftgelenk, Kniegelenkendoprothesen).\r\n\r\nKinder bis 2 Jahren Risikoklasse III.',NULL,'wc4849c7856370e18017151',1511528416894,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('04.3030-20180101-KVG',X'',NULL,NULL,'Wc49b6b4c6abe261c086429',1511528319254,'0');
