INSERT INTO `TARMED_EXTENSION` VALUES ('37.0600-20141001-KVG',X'','Direktausstriche von Feinnadelpunktionen, Sekreten, Bürstenbiopsien usw. sowie Oberflächenabstriche (Registrierung, Färben, Screening inkl. Befundung); gilt auch für gynäkozytologische Abstriche mit fraglich positivem oder positivem Befund.',NULL,'wc4b4220c8a5796f9081951',1511528312511,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('00.0230-20010101-KVG',X'','Beinhaltet: Gespräche mit dem Patienten u/o mit den für den Patienten zuständigen Personen, Visiten bei Patienten (inkl. Wundpflege, Verbandwechsel, Entfernung von Wundverschlussmaterial).\r\n\r\nDefinition Operation/Intervention siehe {4}.\r\n\r\nAbrechenbar ab dem zweiten Tag nach der Operation u/o Intervention u/o während des Wochenbettes bis und mit Austrittstag; nur durch den hauptverantwortlich behandelnden Facharzt abrechenbar.\r\n\r\nFür elektronisch abrechnende Fachärzte siehe (00.0310).',NULL,'Wc4c63faa8fa3720c060179',1511528277739,'0');
