INSERT INTO `TARMED_EXTENSION` VALUES ('37.0700-20141001-KVG',X'','Gilt auch für Sedimentationspräparation oder Filtrationspräparation (sog. Dünnschichtmethode, Liquid-base, Thin-prep, usw.).\r\n\r\nRegistrierung, Färben, Screening, mikroskopischer Befund (konventioneller Papabstrich), Kurzdiagnose durch die Fachperson. \r\n\r\nInkl. Beurteilung der Vaginalflora; für gynäkozytologische Abstriche mit fraglich positivem oder positivem Befund siehe (37.0600), (37.0640), (37.0650).',NULL,'wc5c8d732bf5982d7082001',1511528312594,'0');
