INSERT INTO `TARMED_EXTENSION` VALUES ('36.0010-20010101-KVG',X'','Gilt für ärztliche Leistungen direkt am und für den Patienten durch den vom Spital oder Institut fix besoldeten Spitalarzt in der Notfallstation. \r\n\r\nDie technische Leistung wird über die Tarifpositionen (36.0020) und (36.0030) Nichtärztliche Betreuung in der anerkannten Notfallaufnahme entschädigt. \r\n\r\nWird der Patient im Anschluss an die ärztliche Leistung hospitalisiert, kann diese Tarifposition nicht abgerechnet werden; diese Tarifposition kann nur solange abgerechnet werden, als keine anderen Leistungen ausserhalb Kapitel [36] erbracht werden.',NULL,'Wcadd2b65073dc7c7081679',1511528312098,'0');
