INSERT INTO `TARMED_EXTENSION` VALUES ('28.0070-20010101',X'','Monitored Anesthesia Care (MAC):\r\n\r\nÜberwachung mit oder ohne Sedation und/oder Analgesie auf Verlangen des behandelnden Facharztes bei Eingriffen und diagnostischen Massnahmen mit und ohne vom behandelnden Facharzt gesetzten Lokalanästhesien.\r\n\r\nVoraussetzungen:\r\n\r\n- Perioperative Betreuung durch den Anästhesisten\r\n- Der Anästhesist befindet sich während des Eingriffes/der Massnahme am Patienten und überwacht diesen.\r\n- Der Patient bleibt auf Ansprache weckbar und seine Spontanatmung ohne mechanische Unterstützung suffizient.',NULL,'Wde4e6e449e657a5a017129',1511528416871,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('39.3515-20080101',X'','Gilt für Weichteiluntersuchungen oder Organuntersuchungen, welche im Rahmen einer Gefäss-Sonografie zusätzlich dargestellt werden. Sie sind im Bericht zu erwähnen.',NULL,'wde7807928ace3f0022401',1511528424807,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('30.1870-20010101',X'',NULL,NULL,'Wde9b98d6d4753045017979',1511528418189,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('07.0770-20180101-KVG',X'',NULL,NULL,'Wde9be849ae3fffa4087779',1511528321237,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('04.2610-20141001-KVG',X'','Beinhaltet Präparation und Débridement sowie Vereinigung des proximalen und distalen Stumpfes.\r\n\r\nGilt auch bei noch bestehender, alleiniger Weichteilbrücke.\r\n\r\nGefässnähte (04.2620) und Nervennähte (04.0810). \r\n\r\nGefässtransplantate ((04.1690) ff) und Nerventransplantate ((04.1730) ff).',NULL,'wdedc23b28273c6b4062651',1511528282076,'0');
