INSERT INTO `TARMED_EXTENSION` VALUES ('20.1340-20180101-KVG',X'','Inkl. allf. Biopsie(n), inkl. allf. Fremdkörperentfernung(en), inkl. allf. Polypektomie(n), inkl. allf. Umstechung einer Blutungsquelle, unabhängig von Anzahl.\r\n\r\nExkl. Laparotomie (20.0620)',NULL,'wdff381dac0ef5b15091451',1511528327102,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('24.0220-20141001-KVG',X'','Definition Exploration: Eingehende chirurgische Darstellung zur sicheren Beurteilung der im verletzten Gebiet betroffenen Strukturen (Sehnen, Gefässe, Nerven).\r\n\r\nDefinition komplex: Verletzung unübersichtlich, Verdacht auf Verletzung von Sehnen, Sehnenanhangsgebilden, Gefässen, Nerven; inkl. Débridement; inkl. Blutstillung. \r\n\r\nNicht verrechenbar, wenn das Verletzungsmuster aufgrund der klinischen u/o apparativen Untersuchung bereits vor dem Eingriff feststeht, z.B. bei Amputationen.\r\n\r\nDie Exploration und Therapieplanung ist zwingend im OP-Bericht zu dokumentieren.',NULL,'we09f522dff11499f074151',1511528300000,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('16.04-20010101',NULL,NULL,NULL,'We0b0b8fbedf29017097829',1511528388579,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('00.1430-20050101',X'','Die Dauer der Behandlung richtet sich nach dem Schweregrad der Therapie und dem Allgemeinzustand des Patienten.\r\n\r\nDer Facharzt muss unmittelbar verfügbar sein.\r\n\r\nWechsel: Abgeltung des Aufwands (Raum, Personal, Umlagen, Verbrauchsmaterial unter (CHF 3.--) während des Patientenwechsels.',NULL,'We0b8437c682b44f099579',1511528390213,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('19.1800-20010101-KVG',X'',NULL,NULL,'we0d3a573813d1c70070401',1511528294502,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('20.2250-20010101-KVG',X'','Unabhängig von Anzahl Hämorrhoiden; inkl. Anoskopie.',NULL,'We0e7ac568a53aab2071129',1511528295613,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('15.0730-20050101',X'','Leistungsinhalt:\r\n\r\nKontinuierliche Aufzeichnung von\r\n- Sauerstoffsättigung\r\n- Herzfrequenz\r\n- Atmungstätigkeit (jede Methode)\r\n- Schlaf ({EEG}, {EOG})\r\n- Bewegung und Lage ({EMG}, Aktigrafie).\r\n\r\nInkl. Elektrokardiografie, Videografie, Audiografie und allf. weitere Parameter.\r\n\r\nAllf. ärztliche Beobachtung während der Leistung, Überwachung durch im Schlaflabor anwesende Person.\r\n\r\nDauer mindestens 6 Stunden.\r\n\r\nInkl. obligate, integrative - allenfalls interdisziplinäre - Gesamtbeurteilung.',NULL,'we145a20362e6fe2a07201',1511528401806,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('04.2040-20010101-KVG',X'','Mittel: Sternocleidomastoideus-Lappen, Pectoralis-Lappen, Serratus anterior-Lappen, Rectus anterior-Lappen, Sartorius-Lappen, Gracilis-Lappen, Biceps femoris-Lappen, Semimembranosus-Lappen, Semitendinosus-Lappen, Tibialis anterior-Lappen, Tibialis posterior-Lappen, Soleus-Lappen, Peroneus longus-Lappen und Peroneus brevis-Lappen, Extensor digitus longus-Lappen, Extensor hallucis longus-Lappen, Flexor digitus longus-Lappen, Extensor digitus minimi-Lappen, Abductor hallucis longus-Lappen, Abductor digitus minimi-Lappen.',NULL,'we157e0e2281daf06062451',1511528281731,'0');
