INSERT INTO `TARMED_EXTENSION` VALUES ('03.0135-20090301',X'','Entwicklungspädiatrische Untersuchung, inkl. Auswertung der verwendeten diagnostischen Tests: z.B. bei Gedeihstörung, Essstörung, Schreiverhalten, Schlafstörung, Störung der Autonomieentwicklung, Störung des Sozialverhaltens, Sprachentwicklungsstörung, Störungen des Antriebes, der Wahrnehmung, der Merkfähigkeit, etc.\r\n\r\nEin vermehrter Zeitaufwand muss gegenüber dem Vertrauensarzt begründet werden. \r\n\r\nDarf nur von nicht vom Spital fix besoldeten Fachärzten abgerechnet werden.',NULL,'We1ce6ea52a286bf60329',1511528391469,'0');
