INSERT INTO `TARMED_EXTENSION` VALUES ('03.0015-20180101-KVG',X'','Beinhaltet die Messung von Länge, Gewicht, Kopfumfang im Perzentilenvergleich sowie eines der folgenden Ergänzungspakete: \r\n1. Erweiterte Untersuchung, beinhaltend: kleine Untersuchung 00.0415 sowie mindestens 4 der folgenden Teile:\r\n- Bulbusmotorik, Stereosehen (inkl. allf. Strabismusprüfung)\r\n- Visusprüfung (z.B.Stycar, E-Haken), Farbsehen (mit Sehtafeln)\r\n- einfache Hörprüfung (z.B.Flüstersprache, Lokalisationsaudiometrie)\r\n- Blutdruck inkl. allf. CW-Doppler\r\n- Genitalorgane, Pubertätsmerkmale im Altersvergleich\r\n- Statik und Beweglichkeit der Wirbelsäule, Spontanmotorik der Extremitäten\r\n- Beurteilung des Entwicklungsstandes (nach Manual SGP)\r\n \r\n2. Erweiterte neurologische Untersuchung, mindestens 6 der folgenden Teile:\r\n- Schädelkonfiguration, Schädelauskultation, kraniale Nervenaustrittspunkte\r\n- Beweglichkeit Halswirbelsäule\r\n- Visus, Gesichtsfeld (mit bewegtem Finger), Fundus (Handophthalmoskop)\r\n- Muskeltonus der Extremitäten\r\n- periphere Sehnenreflexe, Pyramidenzeichen\r\n- Spontanmotorik und Koordination der Extremitäten (mindestens je 3 Tests)\r\n- Oberflächensensibilität und Tiefensensibilität der Extremitäten (orientierend)\r\n- Blutdruck inkl. allf. CW-Doppler\r\n \r\nDie durchgeführten Untersuchungen müssen in der Patientenakte aufgeführt werden.',NULL,'Wfee49db25f736020085679',1511528318059,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('20.1840-20010101',X'','Exkl. Laparotomie (20.0620).',NULL,'wff22b5b0dec1d3d5010051',1511528406278,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('04.2570-20141001-KVG',X'','Beinhaltet Präparation und Débridement sowie Vereinigung des proximalen und distalen Stumpfes; inkl. allf. Muskelnähte.\r\n\r\nGilt auch bei noch bestehender, alleiniger Weichteilbrücke.\r\n\r\nGefässnähte (04.2620) und Nervennähte [05.03.02].\r\n\r\nGefässtransplantate ((04.1690) ff) und Nerventransplantate ((04.1730) ff).\r\n\r\nOsteosynthesen [24.03].\r\n\r\nSehnennähte (04.0720).',NULL,'Wff2b57c898ec9ec7062629',1511528282037,'0');
