INSERT INTO `TARMED_EXTENSION` VALUES ('32.0655-20080101-KVG',X'','Therapie mit adaptiertem/dediziertem Bestrahlungsgerät.\r\n\r\nBeinhaltet Überprüfung der Indikation, Festlegung des Untersuchungsganges, Weisungen und Erklärungen an Fachpersonal und Patienten. {TL} und {AL} beinhalten abschliessend die Aktivitäten zur\r\n\r\n1. Vorbereitung: {CT}/{MRI}/Angio Grundleistungen, {OP}-Benützung, Zielpunktbestimmung mit Anlegen des Rahmens, allfällige Anästhesieleistungen in der Vorbereitung.\r\n\r\n2. Bestrahlungsphase: Die Planung, Zuschlag für aufwändige Planung und die Einmalbestrahlung.\r\n\r\nAm Bestrahlungstag sind somit keine weiteren Aufnahmen im Schädel-Hirnbereich mit {CT} oder {MRI} möglich. Nicht inbegriffen sind Leistungen der Tagesklinik.',NULL,'xc8f80df6c38c74d6081070',1511528311217,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('08.1690-20180101-KVG',X'',NULL,NULL,'xc922fa982b141e4b088320',1511528322123,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('00.0516-20180101-KVG',X'','Abrechenbar im Ausnahmefall bei Patienten über 6 Jahren und unter 75 Jahren mit einem erhöhten Behandlungsbedarf.\r\n\r\nDie Gründe für den erhöhten Behandlungsbedarf eines Patienten müssen in der Patientenakte aufgeführt werden. Der erhöhte Behandlungsbedarf eines Patienten ist gegenüber dem Versicherer zu begründen.\r\n\r\nGilt insbesondere für:\r\n\r\nDiätberatung: Gewichtsreduktion; bei Diabetes, Hyperlipämie und anderen Stoffwechselkrankheiten; Abgabe und Besprechung von Diätplänen.\r\n\r\nSozialberatung: Information über soziale Institutionen wie Gemeindehilfe, Spitex, Tagesspital, Fürsorge.\r\n\r\nRehabilitationsberatung: nach Unfall, Herzinfarkt, cerebralem Insult und bei Langzeitleiden; Information über Zielsetzung, Inhalt der entsprechenden Rehabilitation und Motivation.\r\n\r\nSuchtberatung: Prävention von Medikamentenabusus und Suchtmittelabusus; Ansprechen des Problems, Aufzeigen von Lösungswegen und Motivation.\r\n\r\nSportmedizinische Beratung: Training, Belastungsgrenzen.\r\n\r\nAllergologische Beratung: Erläuterung individueller, expositionsprophylaktischer Massnahmen, Verhaltensinstruktion bei Erkrankungen inkl. Notfallset.\r\n\r\nErgonomische Beratung: Rückenhygiene und Gelenkshygiene im beruflichen und privaten Bereich; gelenkschonende Verhaltensweisen und spezielle Hilfsmittel bei {pcP}-Patienten.\r\n\r\nDie Beratungen beinhalten Hinweise auf Drucksachen, Beratungsstellen und andere Fachstellen sowie Selbsthilfegruppen, jedoch nicht das Herstellen von Kontakten mit diesen Institutionen.',NULL,'xc946de42ebee0992084820',1511528316828,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('05.2460-20141001-KVG',X'',NULL,NULL,'xc95be4f47ff4773c064170',1511528284421,'0');
