INSERT INTO `TARMED_EXTENSION` VALUES ('35.0210-20141001',X'','Gilt nur bei Behandlung ambulanter und somatischer Tagesklinikpatienten. \r\n\r\nDie Tarifposition beinhaltet folgende Tätigkeiten durch nichtärztliches Personal: Operationsvorbereitung, Prämedikation, Information und Anweisungen an den Patienten, Medikation und Wundpflege, Überwachung und Pflege bis zum Austritt; inkl. Bettbenützung, Mahlzeiten und Getränke usw.. \r\n\r\nGrundsätzlich kann die nichtärztliche Betreuung nur bis zur Stabilisierung aller vitalen Funktionen verrechnet werden, nämlich: Erlangen des Bewusstseins, normale(r) Atmung und Kreislauf, Schmerzempfindung und Beweglichkeit usw.; gilt auch für somatische postinterventionelle Betreuung, internistische Überwachung, sowie intubierte Patienten.\r\n\r\nGilt auch für die Betreuung/Überwachung vor und nach ambulanten Eingriffen in gemäss Spartenkonzept anerkannten Operationssälen und der interventionellen Schmerztherapie sowohl im Spital als auch in der Arztpraxis.',NULL,'y2154f05d9a59b39020619',1511528422188,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('37.0435-20050101-KVG',X'','Jede Spezialfärbung bedarf einer diagnostischen Indikation; mehrfach pro Block möglich.',NULL,'y2163775cce8d5727081869',1511528312381,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('06.1750-20180101-KVG',X'','Skoliose mehr als 20°, Kyphose mehr als 10°, mehr als 2 Segmente.',NULL,'Y216fbff7cf6b5452087528',1511528320878,'0');
