INSERT INTO `TARMED_EXTENSION` VALUES ('00.0163-20180101-KVG',X'','Gilt für Auskünfte an Angehörige oder andere Bezugspersonen des Patienten  (mündlich oder telefonisch) in Abwesenheit des Patienten .\r\n\r\nAbrechenbar im Ausnahmefall bei Patienten über 6 Jahren und unter 75 Jahren mit einem erhöhten Behandlungsbedarf.\r\nDie Gründe für den erhöhten Behandlungsbedarf eines Patienten müssen in der Patientenakte aufgeführt werden. Der erhöhte Behandlungsbedarf eines Patienten ist gegenüber dem Versicherer zu begründen.\r\n\r\nGilt nicht für Auskünfte an Angehörige oder andere Bezugspersonen des Patienten, die in Zusammenhang mit der Erstellung von ärztlichen Zeugnissen, Berichten und Schreiben nach Kapitel [00.06], erbracht werden.\r\n\r\nMenge: gemäss Limitation in LG-11',NULL,'Y22ae57d33eadc1aa084728',1511528316713,'0');
