INSERT INTO `TARMED_EXTENSION` VALUES ('28.0050-20010101',X'','Bei Mehrfacheingriffen kommt die höher verrechenbare Risikoklasse zur Anwendung. \r\n\r\nDie perioperative Betreuung beinhaltet: Prämedikation am Vortag oder am Operationstag mit persönlicher Visite des Anästhesisten, allenfalls auch ambulant vorgezogen; postoperative ärztliche Behandlung am Operationstag in der Aufwachstation oder auf der Krankenabteilung bis zum Arbeitsbeginn des nächsten Tages u/o bei {IPS}-Patienten bis eine Stunde nach Operationsende. \r\n\r\nAnästhesieleistung mit stark erhöhtem Risiko:\r\n\r\n- Laparotomien (ausgenommen Appendektomie )\r\n- Thorakotomien\r\n- Lumbotomien\r\n- Kraniotomien\r\n- Wirbelsäulenoperationen\r\n- laparoskopische, thorakoskopische Eingriffe\r\n- maxilläre, rhinologische, orale, pharyngeale, laryngologische Eingriffe\r\n- Endoskopien über Mund/Nase\r\n- Kinder bis zu 2 Jahren (ausgenommen operative Versorgung Risikoklasse IV).',NULL,'y340436ef3d56fe20017119',1511528416853,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('24.3770-20010101',X'',NULL,NULL,'Y340d80071170df80014528',1511528412887,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('24.3330-20010101',X'','Daumen-Metacarpo-Phalangeal-Gelenk.',NULL,'Y34324360dae14016014378',1511528412651,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('34.0210-20010101-KVG',X'','Die pflegerischen Leistungen kommen nur bei einem stationären Aufenthalt zur Anwendung. \r\n\r\nDie pflegerischen Leistungen {IPS} Neonatologie umfassen die Benutzung der Räumlichkeiten sowie der Geräte und Instrumente, die pflegerischen Tätigkeiten (Grundpflege und Behandlungspflege) inkl. Analyse, welche vom {IPS}-Personal mit den dort zur Verfügung stehenden Laborgeräten und Materialien vorgenommen werden können. \r\n\r\nDie diversen Tätigkeiten, z.B. Vor- und Nachbereitung der Isolette, Beatmungsgeräte und Überwachungsgeräte, Austauschtransfusionen usw. sind in dieser Tarifposition einberechnet. \r\n\r\nBei jedem Eintritt in die {IPS} Neonatologie kann für die ersten 2 Std. diese Tarifposition abgerechnet werden; nach Ablauf der ersten 2 Std. wird der Patient in eine der 4 {SGI}-Pflegekategorien eingeteilt. \r\n\r\nBei der Reanimation eines Neugeborenen kommt für die nichtärztliche Betreuung diese Tarifposition (34.0210) und nach Ablauf von zwei Stunden Patienten-Kategorie 1B (34.0230) zur Anwendung; dies gilt auch für die Austauschtransfusion.',NULL,'Y344b028544d0428081478',1511528311797,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('30.3140-20010101',X'',NULL,NULL,'Y3450046b288d77e3018428',1511528418800,'0');
