INSERT INTO `TARMED_EXTENSION` VALUES ('04.1180-20141001-KVG',X'','Gilt für chronische Wunden oder bei Wunden wie diabetischer Fuss, Dekubiti, onkologische Wunden, Versorgung von Fisteln. Kann nur in Spitälern gemäss Art 39 {KVG} und Einrichtungen der ambulanten Krankenpflege gemäss Art 36a {KVG}  abgerechnet werden.',NULL,'yf859c2c9994a5026062119',1511528281110,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('36.0030-20010101',X'','Die pflegerischen Leistungen umfassen die Überwachung und die Betreuung des Notfallpatienten wie z.B. Kontrolle des Allgemeinzustandes (Bewusstsein, Blutdruck, Puls, Pupillenreaktionen, Zentralvenendruck usw.); Dokumentationen, Instruktionen usw.. \r\n\r\nDie Tarifposition darf nicht mehr abgerechnet werden, sobald der Patient die Notfallaufnahme definitiv verlässt (Austritt oder Verlegung); organisatorisch bedingte Wartezeiten können nicht abgerechnet werden. \r\n\r\nWird der Patient im Anschluss an die ärztliche Leistung hospitalisiert, kann diese Tarifposition nicht abgerechnet werden; diese Tarifposition kann nur solange abgerechnet werden, als keine anderen Leistungen ausserhalb Kapitel [36] erbracht werden.',NULL,'yf85f5f756a00c323020669',1511528422257,'0');
INSERT INTO `TARMED_EXTENSION` VALUES ('00.2570-20180101-KVG',X'','Kriterien telefonische Notfallkonsultation (tarifarisch):\r\n \r\n- Medizinisch notwendig und/oder vom Patienten, Angehörigen oder Dritten als offensichtlich notwendig erachtet.\r\n \r\n- Der Facharzt befasst sich sofort, verzugslos mit dem Anrufenden.\r\n \r\n- Gespräch innerhalb oder und ausserhalb der eigenen Arztpraxis.\r\n \r\nFür die Entschädigung massgebend ist der Zeitpunkt des effektiven telefonischen Kontaktes.\r\n \r\nZuschlag von 25% auf den Tarifpositionen telefonische Konsultation, die in diesem Zeitraum für die Behandlung des entsprechenden Notfalls verrechnet werden.\r\n \r\nZuschlag nur auf die AL und nicht auf die TL der entsprechenden Tarifpositionen.\r\n \r\nDarf nur von nicht vom Spital oder Institut fix besoldeten Fachärzten abgerechnet werden.',NULL,'Yf89d6384165c009a085428',1511528317685,'0');
