INSERT INTO `TARMED_EXTENSION` VALUES ('38.0450-20070401-KVG',X'','Inkl. Spirometrie gemäss (15.0130); inkl. Grundtaxe Röntgen Arztpraxis gemäss (39.0021); inkl. technische Grundleistung gemäss (39.2000); inkl. Thoraxradiografie gemäss (39.0190); inkl. kleiner Arztbericht gemäss (00.2255).\r\n\r\nZusätzlich sind gemäss Analysenliste mit Tarif (AL) verrechenbar:\r\n\r\n1666.00 Senkungsreaktion, exkl. Blutentnahme \r\n1396.00 Hämoglobin \r\n1532.00 Leukozytenzählung \r\n1266.00 Differenzialblutbild, Ausstrich, mikroskopisch \r\n1715.00 Thrombozytenzählung \r\n1020.00 {ALAT} \r\n1341.00 Gamma-GT \r\n1739.00 Urinstatus \r\n1509.00 Kreatinin',NULL,'Z38b1ed9d9550b67e082189',1511528312933,'0');
