INSERT INTO `TARMED_EXTENSION` VALUES ('09.0010-20010101-KVG',X'','Fachspezifische Anamnese, klinische Beurteilung Ohr, Ohrmuschel, Gehörgang und Trommelfell mit Ohrmikroskop/Lupe, Stimmgabelprüfung (Weber, Rinné), Flüsterzahlen, Beurteilung der vorderen Nasenräume mit Spekulum (vordere Rhinoskopie). \r\n\r\nBeurteilung von Epipharynx mit Spiegel; eventuell Beurteilung der Sinus maxillaris mittels Diaphanoskopie; visuelle Beurteilung von Lippe, Gebiss, Zahnfleisch, Zunge, Mundschleimhaut, Tonsillen, Mesopharynx (enoraler Status). \r\n\r\nBeurteilung von Hypopharynx und Larynx mittels Spiegel (indirekte Laryngoskopie); äussere Palpation von Hals und Nacken.',NULL,'Zfe68073d8b3a25ad066689',1511528288430,'0');
